window.__X_NEWS__ = {"updated_at": "2026-10-22 01:10 Asia/Shanghai", "updated_at_iso": "2026-10-21T17:10:12.000Z", "count": 90, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112386205996245100", "domain": "科技", "title_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development", "title_zh": "奥特曼勾勒先进 AI 安全发展的三条路径", "hook_en": "Sam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.", "hook_zh": "萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。", "summary_en": "Last week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures. The talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "summary_zh": "上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "body_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development.\n\nSam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.\n\nLast week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures.\n\nThe talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "body_zh": "奥特曼勾勒先进 AI 安全发展的三条路径。\n\n萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。\n\n上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。\n\n谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "url": "https://x.com/i/trending/2112386205996245100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T14:10:55.000Z"}, {"id": "2112176711844458620", "domain": "科技", "title_en": "Anthropic Commits Shares to Public Benefit Fund", "title_zh": "Anthropic 设立公益基金，承诺拨出股份服务公共目的", "hook_en": "Anthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.", "hook_zh": "Anthropic 宣布把约 5% 股份用于公益，回应“AI 带来普遍丰裕”的期待。", "summary_en": "The AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline. Combined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "summary_zh": "这家推出 Claude 的公司宣布设立“公益基金”，起步拨出 5% 股份（须经股东批准），估值每高出基准 50% 还可再增拨最多 2%。加上此前承诺，约合 20% 股份可用于非营利捐赠、援助受影响群体或应对就业冲击等，并延续其 2 亿美元劳工研究投入，且不用于游说。埃隆·马斯克回应称自己也会这么做，并提到“普遍高收入”，引发关于如何分享 AI 红利的讨论。", "body_en": "Anthropic Commits Shares to Public Benefit Fund.\n\nAnthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.\n\nThe AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline.\n\nCombined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "body_zh": "Anthropic 设立公益基金，承诺拨出股份服务公共目的。\n\nAnthropic 宣布把约 5% 股份用于公益，回应“AI 带来普遍丰裕”的期待。\n\n这家推出 Claude 的公司宣布设立“公益基金”，起步拨出 5% 股份（须经股东批准），估值每高出基准 50% 还可再增拨最多 2%。\n\n加上此前承诺，约合 20% 股份可用于非营利捐赠、援助受影响群体或应对就业冲击等，并延续其 2 亿美元劳工研究投入，且不用于游说。埃隆·马斯克回应称自己也会这么做，并提到“普遍高收入”，引发关于如何分享 AI 红利的讨论。", "url": "https://x.com/i/trending/2112176711844458620", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:34:55.000Z"}, {"id": "2112343868393816356", "domain": "科技", "title_en": "NVIDIA Unveils Modular AI Factories Slashing Deployment to 14 Days", "title_zh": "英伟达发布模块化 AI 工厂，部署最短可压至 14 天", "hook_en": "Imagine turning months of AI factory construction into just 14 days of setup. NVIDIA's new DSX POD system makes that possible, delivering pre-built, fully wired containers ready to plug in.", "hook_zh": "把原本需要数月的 AI 工厂建设压缩到约 14 天——英伟达新的 DSX POD 系统把预装、全接线的集装箱直接交付，插上即可用。", "summary_en": "At GTC Berlin, NVIDIA introduced the DSX POD reference design, which packs complete Vera Rubin AI factories into factory-tested containers for partners to integrate off-site. This cuts deployment from months to as little as 14 days, addressing key bottlenecks in data center builds and speeding up revenue from token production, as CEO Jensen Huang emphasized. The event spotlighted European cloud provider Nebius, praised by Huang for its strong performance, with CEO Arkady Volozh noting robust demand and expansion plans targeting $8 billion in annual recurring revenue. DSX POD units will roll out worldwide in early 2027, boosting Europe's AI ecosystem.", "summary_zh": "在柏林 GTC 上，英伟达推出 DSX POD 参考设计，把完整的 Vera Rubin AI 工厂装进经工厂测试的集装箱，供合作伙伴异地集成。部署周期可由数月缩短至最短约 14 天，缓解数据中心建设瓶颈，并加快代币生产带来的收入，CEO 黄仁勋对此着重强调。活动还聚焦欧洲云服务商 Nebius，黄仁勋称赞其表现强劲；CEO Arkady Volozh 表示需求旺盛，扩张目标指向约 80 亿美元年经常性收入。DSX POD 单元计划于 2027 年初在全球推出，助力欧洲 AI 生态。", "body_en": "NVIDIA Unveils Modular AI Factories Slashing Deployment to 14 Days.\n\nImagine turning months of AI factory construction into just 14 days of setup. NVIDIA's new DSX POD system makes that possible, delivering pre-built, fully wired containers ready to plug in.\n\nAt GTC Berlin, NVIDIA introduced the DSX POD reference design, which packs complete Vera Rubin AI factories into factory-tested containers for partners to integrate off-site. This cuts deployment from months to as little as 14 days, addressing key bottlenecks in data center builds and speeding up revenue from token production, as CEO Jensen Huang emphasized.\n\nThe event spotlighted European cloud provider Nebius, praised by Huang for its strong performance, with CEO Arkady Volozh noting robust demand and expansion plans targeting $8 billion in annual recurring revenue. DSX POD units will roll out worldwide in early 2027, boosting Europe's AI ecosystem.", "body_zh": "英伟达发布模块化 AI 工厂，部署最短可压至 14 天。\n\n把原本需要数月的 AI 工厂建设压缩到约 14 天——英伟达新的 DSX POD 系统把预装、全接线的集装箱直接交付，插上即可用。\n\n在柏林 GTC 上，英伟达推出 DSX POD 参考设计，把完整的 Vera Rubin AI 工厂装进经工厂测试的集装箱，供合作伙伴异地集成。部署周期可由数月缩短至最短约 14 天，缓解数据中心建设瓶颈，并加快代币生产带来的收入，CEO 黄仁勋对此着重强调。\n\n活动还聚焦欧洲云服务商 Nebius，黄仁勋称赞其表现强劲；CEO Arkady Volozh 表示需求旺盛，扩张目标指向约 80 亿美元年经常性收入。DSX POD 单元计划于 2027 年初在全球推出，助力欧洲 AI 生态。", "url": "https://x.com/i/trending/2112343868393816356", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T14:42:01.000Z"}, {"id": "2112630070984802593", "domain": "科技", "title_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations", "title_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天", "hook_en": "Ever had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.", "hook_zh": "把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 或生物识别就能搞定。", "summary_en": "The feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile. Locked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "summary_zh": "用户可将聊天移入受保护区域，从历史、置顶与搜索中隐藏，需四位 PIN（全平台）或手机生物识别才能打开。功能自 10 月 20 日起覆盖免费到企业、教育等各档套餐的网页、桌面与移动端。锁定对话的新消息进入独立记忆分区，不影响普通聊天；但不提供端到端加密，重置 PIN 后也无法恢复。此举回应了围绕 ChatGPT 记忆与隐私的讨论。", "body_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations.\n\nEver had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.\n\nThe feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile.\n\nLocked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "body_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天。\n\n把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 或生物识别就能搞定。\n\n用户可将聊天移入受保护区域，从历史、置顶与搜索中隐藏，需四位 PIN（全平台）或手机生物识别才能打开。功能自 10 月 20 日起覆盖免费到企业、教育等各档套餐的网页、桌面与移动端。\n\n锁定对话的新消息进入独立记忆分区，不影响普通聊天；但不提供端到端加密，重置 PIN 后也无法恢复。此举回应了围绕 ChatGPT 记忆与隐私的讨论。", "url": "https://x.com/i/trending/2112630070984802593", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T08:41:04.000Z"}, {"id": "2112684362596766177", "domain": "科技", "title_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots", "title_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具", "hook_en": "Imagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.", "hook_zh": "一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。", "summary_en": "Viggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video. Dream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "summary_zh": "Viggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。Dream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "body_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots.\n\nImagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.\n\nViggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video.\n\nDream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "body_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具。\n\n一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。\n\nViggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。\n\nDream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "url": "https://x.com/i/trending/2112684362596766177", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T23:23:26.000Z"}, {"id": "2112595601669919101", "domain": "科技", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion.\n\nCritics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温。\n\nOpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。\n\n去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。\n\n综合以上信息，OpenAI 对限制对华出口 AI 芯片的立场明显降温一事持续引发关注。", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z"}, {"id": "2112540739628630161", "domain": "科技", "title_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors", "title_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片", "hook_en": "Amazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.", "hook_zh": "大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。", "summary_en": "The company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake. This comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "summary_zh": "公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "body_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors.\n\nAmazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.\n\nThe company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake.\n\nThis comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "body_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片。\n\n大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。\n\n公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。\n\n有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "url": "https://x.com/i/trending/2112540739628630161", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "AI"], "updated_at": "2026-10-20T13:52:24.000Z"}, {"id": "2112741574346162483", "domain": "科技", "title_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO", "title_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO", "hook_en": "Firmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.", "hook_zh": "Firmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。", "summary_en": "Australian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million. This move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "summary_zh": "澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "body_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO.\n\nFirmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.\n\nAustralian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million.\n\nThis move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "body_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO。\n\nFirmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。\n\n澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。\n\n此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "url": "https://x.com/i/trending/2112741574346162483", "category": "News", "topics": ["Technology", "AI", "Business & Finance"], "updated_at": "2026-10-21T04:17:50.000Z"}, {"id": "2112496630352281688", "domain": "科技", "title_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage", "title_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心", "hook_en": "Microsoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.", "hook_zh": "得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。", "summary_en": "Nscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong. Nscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "summary_zh": "Nscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。Nscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "body_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage.\n\nMicrosoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.\n\nNscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong.\n\nNscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "body_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心。\n\n得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。\n\nNscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。\n\nNscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "url": "https://x.com/i/trending/2112496630352281688", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T10:54:58.000Z"}, {"id": "2112290597440745963", "domain": "科技", "title_en": "Merz Hosts Nvidia's Huang in Berlin to Boost German AI Investments", "title_zh": "默茨在柏林会见英伟达黄仁勋，推动德国 AI 投资", "hook_en": "In Berlin, Chancellor Friedrich Merz sat down with Nvidia CEO Jensen Huang, urging Germany to lead in industrial AI by blending its engineering prowess with cutting-edge tech.", "hook_zh": "德国总理弗里德里希·默茨与英伟达 CEO 黄仁勋会面，呼吁以工程实力引领工业 AI。", "summary_en": "At the Invest in Germany Summit on October 19, Merz welcomed global investors and discussed AI regulation with Huang, who stressed that thriving industry must come before rules, with safety rooted in engineering and best practices. Nvidia announced investments in four German startups—Agile Robots, Avelios Medical, Mirelo, and Reflex Aerospace—as part of its $10 billion European commitment, and signed a deal with the government for advanced physical AI models using German industrial data. Huang praised Germany's irreplaceable engineering, noting Nvidia's 1,000 local employees and nearly $1 billion invested last year, while Merz highlighted the nation's strong industrial base and market access to shape its economic future.", "summary_zh": "在 10 月 19 日“投资德国峰会”上，默茨与黄仁勋讨论 AI 监管；黄仁勋强调产业繁荣应先于规则，安全植根于工程与最佳实践。英伟达宣布投资 Agile Robots、Avelios Medical、Mirelo、Reflex Aerospace 四家德国初创，并纳入其 100 亿美元欧洲承诺，同时与德国政府就基于本土工业数据的物理 AI 模型达成合作。黄仁勋称赞德国工程不可替代，并提到英伟达在当地约有 1000 名员工、去年投资近 10 亿美元。", "body_en": "Merz Hosts Nvidia's Huang in Berlin to Boost German AI Investments.\n\nIn Berlin, Chancellor Friedrich Merz sat down with Nvidia CEO Jensen Huang, urging Germany to lead in industrial AI by blending its engineering prowess with cutting-edge tech.\n\nAt the Invest in Germany Summit on October 19, Merz welcomed global investors and discussed AI regulation with Huang, who stressed that thriving industry must come before rules, with safety rooted in engineering and best practices.\n\nNvidia announced investments in four German startups—Agile Robots, Avelios Medical, Mirelo, and Reflex Aerospace—as part of its $10 billion European commitment, and signed a deal with the government for advanced physical AI models using German industrial data. Huang praised Germany's irreplaceable engineering, noting Nvidia's 1,000 local employees and nearly $1 billion invested last year, while Merz highlighted the nation's strong industrial base and market access to shape its economic future.", "body_zh": "默茨在柏林会见英伟达黄仁勋，推动德国 AI 投资。\n\n德国总理弗里德里希·默茨与英伟达 CEO 黄仁勋会面，呼吁以工程实力引领工业 AI。\n\n在 10 月 19 日“投资德国峰会”上，默茨与黄仁勋讨论 AI 监管；黄仁勋强调产业繁荣应先于规则，安全植根于工程与最佳实践。\n\n英伟达宣布投资 Agile Robots、Avelios Medical、Mirelo、Reflex Aerospace 四家德国初创，并纳入其 100 亿美元欧洲承诺，同时与德国政府就基于本土工业数据的物理 AI 模型达成合作。黄仁勋称赞德国工程不可替代，并提到英伟达在当地约有 1000 名员工、去年投资近 10 亿美元。", "url": "https://x.com/i/trending/2112290597440745963", "category": "News", "topics": ["Technology", "Politics"], "updated_at": "2026-10-20T20:55:18.000Z"}, {"id": "2112905930044317939", "domain": "科技", "title_en": "NVIDIA and University of Washington Release RFD4-Proteina for Protein Design", "title_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计", "hook_en": "Imagine designing proteins—from enzymes to antibodies—in one seamless step, 13 times faster than before. That's the breakthrough from NVIDIA and the University of Washington's Baker Lab.", "hook_zh": "英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。", "summary_en": "RFD4-Proteina, a new open AI model, reasons across amino acids, sugars, DNA, and RNA to co-design a protein's sequence and 3D structure together. Born from a year-long collaboration with Nobel laureate David Baker's team, it excels on benchmarks, speeds up generation for 200-residue proteins, and has produced real-world successes like an enzyme for the HIV drug lenacapavir. Available now on GitHub, Hugging Face, and as an NVIDIA service, it's already drawing excitement from scientists for accelerating drug discovery and enzyme engineering.", "summary_zh": "RFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "body_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design.\n\nScientists at NVIDIA and the University of Washington just dropped a powerful new AI tool that designs proteins quicker and better than before. It's already drawing cheers for speeding up drug discovery.\n\nRFD4-Proteina, born from a year-long collaboration between NVIDIA's GenAIR team and the Baker Lab at UW's Institute for Protein Design, co-designs protein sequences and structures in a shared latent space. It handles binder design, enzyme scaffolding, motif conditioning, and work with DNA, RNA, or small molecules, outperforming prior models in speed, quality, and wet-lab success rates.\n\nReleased open source on GitHub and Hugging Face at GTC Berlin, it's available as an NVIDIA NIM microservice and integrated with partners like Tamarind Bio for easy use. Researchers called the results 'astonishing' and a state-of-the-art leap for biology and medicine.", "body_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计。\n\n英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。\n\nRFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。\n\n该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "url": "https://x.com/i/trending/2112905930044317939", "category": "News", "topics": ["Technology", "AI", "Biotech"], "updated_at": "2026-10-21T16:58:22.000Z"}, {"id": "2112883740699480270", "domain": "科技", "title_en": "OpenAI Partners with Google Cloud to Offer Frontier Models in Model Garden", "title_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden", "hook_en": "OpenAI's powerful models like GPT-6 Astra are landing on Google Cloud, giving businesses a unified spot to access top AI tools without juggling platforms.", "hook_zh": "GPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。", "summary_en": "Google Cloud announced today that enterprise customers can soon use OpenAI's frontier models, including GPT-6 Astra and Codex agentic workflows, directly in its Model Garden alongside Gemini, Claude, and over 200 others. Businesses can purchase through the Google Cloud Marketplace, apply existing spending commitments, and integrate into tools like Google Antigravity and Gemini Agent for flexible task handling. This expands OpenAI's reach beyond Microsoft Azure—now non-exclusive—to more cloud options, supporting regulated industries with strong data governance and high-performance setup. Analysts see it as a win for multi-model strategies and easier AI adoption.", "summary_zh": "谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "body_en": "OpenAI Partners with Google Cloud to Offer Frontier Models in Model Garden.\n\nOpenAI's powerful models like GPT-6 Astra are landing on Google Cloud, giving businesses a unified spot to access top AI tools without juggling platforms.\n\nGoogle Cloud announced today that enterprise customers can soon use OpenAI's frontier models, including GPT-6 Astra and Codex agentic workflows, directly in its Model Garden alongside Gemini, Claude, and over 200 others. Businesses can purchase through the Google Cloud Marketplace, apply existing spending commitments, and integrate into tools like Google Antigravity and Gemini Agent for flexible task handling.\n\nThis expands OpenAI's reach beyond Microsoft Azure—now non-exclusive—to more cloud options, supporting regulated industries with strong data governance and high-performance setup. Analysts see it as a win for multi-model strategies and easier AI adoption.", "body_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden。\n\nGPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。\n\n谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。\n\n此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "url": "https://x.com/i/trending/2112883740699480270", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:08:05.000Z"}, {"id": "2112281282239664552", "domain": "科技", "title_en": "NVIDIA Runs Record 104-Qubit Quantum Simulation on JUPITER Supercomputer", "title_zh": "英伟达在 JUPITER 超算上完成创纪录 104 量子比特模拟", "hook_en": "NVIDIA researchers pushed classical computing to mimic a fault-tolerant quantum system with 104 qubits—the largest simulation yet—using thousands of GPUs in Germany.", "hook_zh": "英伟达研究人员用德国数千块 GPU，推动经典计算模拟容错量子系统，达 104 量子比特——迄今最大规模。", "summary_en": "On Europe’s JUPITER supercomputer at the Jülich Supercomputing Centre, NVIDIA simulated a 104-qubit fault-tolerant quantum processor with 8,192 GH200 GPUs, including realistic hardware noise that past efforts overlooked. The simulation validated magic state cultivation, a method that slashes physical qubit needs by about 90 percent, guiding error mitigation for drug discovery, financial modeling, and materials science. CEO Jensen Huang highlighted how such digital twins of factories will let workers design AI cars and robotic plants virtually first. This bridges GPU simulations with real quantum hardware, de-risking development and speeding practical machines.", "summary_zh": "在于利希超算中心的欧洲 JUPITER 超算上，英伟达用 8192 块 GH200 GPU 模拟了 104 量子比特容错量子处理器，并纳入以往常被忽略的真实硬件噪声。模拟验证了「魔法态培育」方法，可将物理量子比特需求削减约 90%，为药物发现、金融建模与材料科学的误差缓解提供指引。CEO 黄仁勋强调，此类工厂数字孪生可让工人先虚拟设计 AI 汽车与机器人产线。此举衔接 GPU 模拟与真实量子硬件，降低开发风险并加速实用化。", "body_en": "NVIDIA Runs Record 104-Qubit Quantum Simulation on JUPITER Supercomputer.\n\nNVIDIA researchers pushed classical computing to mimic a fault-tolerant quantum system with 104 qubits—the largest simulation yet—using thousands of GPUs in Germany.\n\nOn Europe’s JUPITER supercomputer at the Jülich Supercomputing Centre, NVIDIA simulated a 104-qubit fault-tolerant quantum processor with 8,192 GH200 GPUs, including realistic hardware noise that past efforts overlooked. The simulation validated magic state cultivation, a method that slashes physical qubit needs by about 90 percent, guiding error mitigation for drug discovery, financial modeling, and materials science.\n\nCEO Jensen Huang highlighted how such digital twins of factories will let workers design AI cars and robotic plants virtually first. This bridges GPU simulations with real quantum hardware, de-risking development and speeding practical machines.", "body_zh": "英伟达在 JUPITER 超算上完成创纪录 104 量子比特模拟。\n\n英伟达研究人员用德国数千块 GPU，推动经典计算模拟容错量子系统，达 104 量子比特——迄今最大规模。\n\n在于利希超算中心的欧洲 JUPITER 超算上，英伟达用 8192 块 GH200 GPU 模拟了 104 量子比特容错量子处理器，并纳入以往常被忽略的真实硬件噪声。模拟验证了「魔法态培育」方法，可将物理量子比特需求削减约 90%，为药物发现、金融建模与材料科学的误差缓解提供指引。\n\nCEO 黄仁勋强调，此类工厂数字孪生可让工人先虚拟设计 AI 汽车与机器人产线。此举衔接 GPU 模拟与真实量子硬件，降低开发风险并加速实用化。", "url": "https://x.com/i/trending/2112281282239664552", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-19T20:43:59.000Z"}, {"id": "2112796521959985524", "domain": "商业", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z"}, {"id": "2112044241161433358", "domain": "商业", "title_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures", "title_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌", "hook_en": "Japanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.", "hook_zh": "日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。", "summary_en": "Japan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers. A South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "summary_zh": "日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "body_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures.\n\nJapanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.\n\nJapan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers.\n\nA South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "body_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌。\n\n日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。\n\n日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。\n\n韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "url": "https://x.com/i/trending/2112044241161433358", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-20T12:59:35.000Z"}, {"id": "2112431560116826201", "domain": "商业", "title_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms", "title_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论", "hook_en": "Subhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.", "hook_zh": "前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。", "summary_en": "Garg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks. Critics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "summary_zh": "加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。IMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "body_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms.\n\nSubhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.\n\nGarg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks.\n\nCritics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "body_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论。\n\n前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。\n\n加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。\n\nIMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "url": "https://x.com/i/trending/2112431560116826201", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T06:36:16.000Z"}, {"id": "2112771431633502285", "domain": "商业", "title_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21", "title_zh": "节后高开后 Nifty 遭遇抛压", "hook_en": "Nifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.", "hook_zh": "排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。", "summary_en": "After Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478. Analysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "summary_zh": "指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "body_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21.\n\nNifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.\n\nAfter Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478.\n\nAnalysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "body_zh": "节后高开后 Nifty 遭遇抛压。\n\n排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。\n\n指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。\n\n布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "url": "https://x.com/i/trending/2112771431633502285", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T08:16:34.000Z"}, {"id": "2112266057628913774", "domain": "商业", "title_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade", "title_zh": "对冲基金十年最快速度抛售科技股", "hook_en": "Hedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.", "hook_zh": "对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。", "summary_en": "Through October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S. tech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "summary_zh": "截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "body_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade.\n\nHedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.\n\nThrough October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S.\n\ntech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "body_zh": "对冲基金十年最快速度抛售科技股。\n\n对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。\n\n截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。\n\n投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "url": "https://x.com/i/trending/2112266057628913774", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:07:55.000Z"}, {"id": "2112507803138973871", "domain": "商业", "title_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto", "title_zh": "美联储购入 18.27 亿美元国债，股币齐涨", "hook_en": "US stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.", "hook_zh": "美联储买入 18.27 亿美元短期国债并于当日交割后，美股与加密货币周二走高，交易员情绪升温。", "summary_en": "The New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves. Bitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "summary_zh": "纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债标售，10 月 20 日交割，属维持银行准备金的常规二级市场购买。比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称流动性注入「巨大」并利好风险资产。交易员关注 11 月前更多既定购买，但也有人指出多为滚动到期持仓，并非显著扩表。", "body_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto.\n\nUS stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.\n\nThe New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves.\n\nBitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "body_zh": "美联储购入 18.27 亿美元国债，股币齐涨。\n\n美联储买入 18.27 亿美元短期国债并于当日交割后，美股与加密货币周二走高，交易员情绪升温。\n\n纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债标售，10 月 20 日交割，属维持银行准备金的常规二级市场购买。\n\n比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称流动性注入「巨大」并利好风险资产。交易员关注 11 月前更多既定购买，但也有人指出多为滚动到期持仓，并非显著扩表。", "url": "https://x.com/i/trending/2112507803138973871", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:09:54.000Z"}, {"id": "2112795004678676841", "domain": "商业", "title_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister", "title_zh": "印度中小盘暴跌，市场怒火指向财长", "hook_en": "Investors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.", "hook_zh": "2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。", "summary_en": "The Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking. Social media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "summary_zh": "Nifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "body_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister.\n\nInvestors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.\n\nThe Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking.\n\nSocial media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "body_zh": "印度中小盘暴跌，市场怒火指向财长。\n\n2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。\n\nNifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。\n\n小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "url": "https://x.com/i/trending/2112795004678676841", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T13:45:53.000Z"}, {"id": "2112620331987062878", "domain": "商业", "title_en": "Investors Surge Protection Purchases on AI Tech Debt", "title_zh": "投资者创纪录买入 CDS，对冲 AI 企业债务风险", "hook_en": "Wall Street traders are snapping up insurance against defaults on massive AI loans, with volumes hitting records as costs climb.", "hook_zh": "AI 公司为数据中心与芯片大举举债之际，投资者正以前所未有的规模买入信用违约互换，防范违约。", "summary_en": "Trading in credit default swaps tied to Nvidia, Meta, Amazon, Alphabet, Microsoft, and others jumped over fourfold to $9 billion weekly in September, fueled by $466 billion in 2026 AI bond sales for data centers and chips. Spreads reached records like Meta's 108 basis points and Nvidia's 101, while riskier names like CoreWeave hit 1,090 amid leverage worries. A report warns of subprime-like risks to pension funds and retirement plans, though analysts point to strong earnings as a counterbalance.", "summary_zh": "与 AI 相关企业在 2026 年累计发行约 4660 亿美元债务，超过去年四倍，支撑大规模数据中心与芯片投资。9 月针对甲骨文、英伟达、Meta 等债券的 CDS 周交易额达 90 亿美元，保护成本飙升——Meta 约 108 个基点、英伟达约 101，CoreWeave 则超过 1000、进入困境区间。分析人士如穆罕默德·埃里安对借贷潮表示不安，亦有报告警示再包装债务卖给养老金等资金或带有类似次贷的风险；也有观点以强劲盈利增长作为对冲论据。", "body_en": "Investors Buy Record CDS to Hedge AI Company Debt Risks.\n\nAs AI firms borrow billions for data centers and chips, investors are snapping up credit default swaps at unprecedented levels to guard against defaults.\n\nAI-linked companies issued $466 billion in debt through 2026, more than quadrupling last year's pace, fueling massive data center and chip investments.\n\nWeekly CDS trading on bonds from Oracle, Nvidia, Meta, and others hit $9 billion in September, with protection costs soaring—Meta at 108 basis points, Nvidia at 101, and CoreWeave over 1,000 in distressed levels. Analysts like Mohamed El-Erian flag unease over the borrowing surge, while reports warn of subprime-like risks in repackaged debt sold to pensions, though some point to strong earnings growth as a counterbalance.", "body_zh": "投资者创纪录买入 CDS，对冲 AI 企业债务风险。\n\nAI 公司为数据中心与芯片大举举债之际，投资者正以前所未有的规模买入信用违约互换，防范违约。\n\n与 AI 相关企业在 2026 年累计发行约 4660 亿美元债务，超过去年四倍，支撑大规模数据中心与芯片投资。\n\n9 月针对甲骨文、英伟达、Meta 等债券的 CDS 周交易额达 90 亿美元，保护成本飙升——Meta 约 108 个基点、英伟达约 101，CoreWeave 则超过 1000、进入困境区间。分析人士如穆罕默德·埃里安对借贷潮表示不安，亦有报告警示再包装债务卖给养老金等资金或带有类似次贷的风险；也有观点以强劲盈利增长作为对冲论据。", "url": "https://x.com/i/trending/2112620331987062878", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T16:34:34.000Z"}, {"id": "2112190708920537480", "domain": "商业", "title_en": "AI Stocks Hit 49% of S&P 500, Echoing 1880s Railroad Peak", "title_zh": "AI 股占标普 500 近半，接近 1880 年代铁路股峰值", "hook_en": "AI stocks now dominate nearly half the S&P 500, a level unseen since railroads ruled markets in the 1880s. Investors wonder if this signals true revolution or another bubble about to burst.", "hook_zh": "AI 相关股票已占标普 500 近一半权重，为 1880 年代铁路股称霸市场以来所未见。投资者争论这是真正的产业革命，还是又一次即将破裂的泡沫。", "summary_en": "AI-related stocks make up 49% of the S&P 500, with the top 10 names holding a record 42% share, surpassing most historical peaks except the 1880s railroad boom. Jamie Dimon sees a booming economy fueled by AI infrastructure spending projected at $1 trillion next year, while Michael Novogratz labels it the biggest bubble of our lifetime. Red flags include a Shiller CAPE ratio near 41, narrow leadership from Nvidia, Apple, and Microsoft at 21% of the index, and only 29% of companies outperforming amid last week's sharp Nasdaq drop. The split pits valuation worries against bets on lasting productivity gains.", "summary_zh": "AI 相关股票约占标普 500 的 49%，前十大成分股权重创纪录达 42%，仅次于 19 世纪铁路繁荣时期的历史峰值。杰米·戴蒙看好由明年约 1 万亿美元 AI 基建开支驱动的经济扩张，迈克尔·诺沃格拉茨则称其为「我们这一生最大的泡沫」。警示信号包括席勒 CAPE 接近 41、英伟达、苹果与微软合计约占指数 21% 的窄幅领涨，以及上周纳指大跌背景下仅 29% 公司跑赢大盘。市场在估值担忧与长期生产率押注之间分裂。", "body_en": "AI Stocks Hit 49% of S&P 500, Echoing 1880s Railroad Peak.\n\nAI stocks now dominate nearly half the S&P 500, a level unseen since railroads ruled markets in the 1880s. Investors wonder if this signals true revolution or another bubble about to burst.\n\nAI-related stocks make up 49% of the S&P 500, with the top 10 names holding a record 42% share, surpassing most historical peaks except the 1880s railroad boom. Jamie Dimon sees a booming economy fueled by AI infrastructure spending projected at $1 trillion next year, while Michael Novogratz labels it the biggest bubble of our lifetime.\n\nRed flags include a Shiller CAPE ratio near 41, narrow leadership from Nvidia, Apple, and Microsoft at 21% of the index, and only 29% of companies outperforming amid last week's sharp Nasdaq drop. The split pits valuation worries against bets on lasting productivity gains.", "body_zh": "AI 股占标普 500 近半，接近 1880 年代铁路股峰值。\n\nAI 相关股票已占标普 500 近一半权重，为 1880 年代铁路股称霸市场以来所未见。投资者争论这是真正的产业革命，还是又一次即将破裂的泡沫。\n\nAI 相关股票约占标普 500 的 49%，前十大成分股权重创纪录达 42%，仅次于 19 世纪铁路繁荣时期的历史峰值。杰米·戴蒙看好由明年约 1 万亿美元 AI 基建开支驱动的经济扩张，迈克尔·诺沃格拉茨则称其为「我们这一生最大的泡沫」。\n\n警示信号包括席勒 CAPE 接近 41、英伟达、苹果与微软合计约占指数 21% 的窄幅领涨，以及上周纳指大跌背景下仅 29% 公司跑赢大盘。市场在估值担忧与长期生产率押注之间分裂。", "url": "https://x.com/i/trending/2112190708920537480", "category": "News", "topics": ["Technology", "AI", "Business & Finance"], "updated_at": "2026-10-19T14:42:06.000Z"}, {"id": "2112413052469481717", "domain": "商业", "title_en": "IREN Shares Drop to $26.62 Near 52-Week Low Amid Funding Worries", "title_zh": "IREN 股价跌至约 26.62 美元，逼近年内低点", "hook_en": "IREN's stock closed at $26.62 on October 20 after a 4% plunge on heavy volume, leaving traders split on whether it's primed for a rebound or more pain ahead.", "hook_zh": "10 月 20 日 IREN 收跌约 4% 至 26.62 美元，成交放大，多空对后市分歧明显。", "summary_en": "The company, once a Bitcoin miner now focused on AI cloud data centers, holds over 5 GW of power capacity and NVIDIA infrastructure powered by renewables, but shares have fallen 65% from their November 2025 peak near $77 due to concerns over $25-30 billion in planned 2027 spending and rising borrowing costs. Traders highlight stretched technical patterns that could snap back up, potential support at Fibonacci levels and the 200-week average, yet some warn of drops to $15-18 if those fail. Wall Street targets stay around $77-81, with early November earnings expected to shed light on demand and funding.", "summary_zh": "这家由比特币矿企转向 AI 云数据中心的公司拥有逾 5GW 电力与英伟达算力基础设施，但相对 2025 年 11 月约 77 美元高点已跌约 65%，市场担忧其 2027 年计划开支达 250–300 亿美元及借贷成本上升。交易者看到技术超卖反弹可能，也有人警示若跌破支撑或探向 15–18 美元。华尔街目标价仍多在 77–81 美元一带，11 月初财报或澄清需求与融资。", "body_en": "IREN Shares Drop to $26.62 Near 52-Week Low Amid Funding Worries.\n\nIREN's stock closed at $26.62 on October 20 after a 4% plunge on heavy volume, leaving traders split on whether it's primed for a rebound or more pain ahead.\n\nThe company, once a Bitcoin miner now focused on AI cloud data centers, holds over 5 GW of power capacity and NVIDIA infrastructure powered by renewables, but shares have fallen 65% from their November 2025 peak near $77 due to concerns over $25-30 billion in planned 2027 spending and rising borrowing costs.\n\nTraders highlight stretched technical patterns that could snap back up, potential support at Fibonacci levels and the 200-week average, yet some warn of drops to $15-18 if those fail. Wall Street targets stay around $77-81, with early November earnings expected to shed light on demand and funding.", "body_zh": "IREN 股价跌至约 26.62 美元，逼近年内低点。\n\n10 月 20 日 IREN 收跌约 4% 至 26.62 美元，成交放大，多空对后市分歧明显。\n\n这家由比特币矿企转向 AI 云数据中心的公司拥有逾 5GW 电力与英伟达算力基础设施，但相对 2025 年 11 月约 77 美元高点已跌约 65%，市场担忧其 2027 年计划开支达 250–300 亿美元及借贷成本上升。\n\n交易者看到技术超卖反弹可能，也有人警示若跌破支撑或探向 15–18 美元。华尔街目标价仍多在 77–81 美元一带，11 月初财报或澄清需求与融资。", "url": "https://x.com/i/trending/2112413052469481717", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T00:39:55.000Z"}, {"id": "2111614021140889617", "domain": "商业", "title_en": "U.S. Job Reports Revised Down by 793,000 Since 2025 Start", "title_zh": "美国就业数据自 2025 年初累计下修 79.3 万个岗位", "hook_en": "Initial job reports promised steady growth, but repeated downward tweaks have wiped out 793,000 positions from the numbers.", "hook_zh": "初值曾描绘稳健增长，但一轮又一轮下修已从数字中抹掉 79.3 万个岗位。", "summary_en": "Since early 2025, U.S. monthly job figures faced lower revisions in 16 of 20 months, slashing a total of 793,000 jobs and leaving 2025's net additions at just 181,000—far below the initial 1.383 million reported. Illinois Governor JB Pritzker highlighted record employment and wages in his state, but critics cited BLS data showing an 80,000-worker labor force drop over the past year and 200,000 fewer employed residents than two decades ago. Observers link some softness to offshoring, like 2.36 million Indian workers supporting U.S. firms, fueling questions on data reliability across political lines.", "summary_zh": "自 2025 年初以来，美国月度就业数据在 20 个月中有 16 个月被下修，累计削减 79.3 万个岗位，使 2025 年净增岗位仅余 18.1 万——远低于最初公布的 138.3 万。伊利诺伊州州长 JB·普利茨克强调本州就业与工资创纪录，批评者则援引劳工统计局数据：过去一年劳动力减少约 8 万人，就业居民比二十年前少约 20 万。观察人士将部分疲软与离岸外包联系起来，例如约 236 万印度劳工支撑美国企业运营，并在党派分野中加剧对数据可信度的质疑。", "body_en": "U.S. Job Reports Revised Down by 793,000 Since 2025 Start.\n\nInitial job reports promised steady growth, but repeated downward tweaks have wiped out 793,000 positions from the numbers.\n\nSince early 2025, U.S. monthly job figures faced lower revisions in 16 of 20 months, slashing a total of 793,000 jobs and leaving 2025's net additions at just 181,000—far below the initial 1.383 million reported.\n\nIllinois Governor JB Pritzker highlighted record employment and wages in his state, but critics cited BLS data showing an 80,000-worker labor force drop over the past year and 200,000 fewer employed residents than two decades ago. Observers link some softness to offshoring, like 2.36 million Indian workers supporting U.S. firms, fueling questions on data reliability across political lines.", "body_zh": "美国就业数据自 2025 年初累计下修 79.3 万个岗位。\n\n初值曾描绘稳健增长，但一轮又一轮下修已从数字中抹掉 79.3 万个岗位。\n\n自 2025 年初以来，美国月度就业数据在 20 个月中有 16 个月被下修，累计削减 79.3 万个岗位，使 2025 年净增岗位仅余 18.1 万——远低于最初公布的 138.3 万。\n\n伊利诺伊州州长 JB·普利茨克强调本州就业与工资创纪录，批评者则援引劳工统计局数据：过去一年劳动力减少约 8 万人，就业居民比二十年前少约 20 万。观察人士将部分疲软与离岸外包联系起来，例如约 236 万印度劳工支撑美国企业运营，并在党派分野中加剧对数据可信度的质疑。", "url": "https://x.com/i/trending/2111614021140889617", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-19T20:56:04.000Z"}, {"id": "2112319265076367697", "domain": "商业", "title_en": "Jio Platforms IPO Fully Subscribed in 100 Minutes on Opening Day", "title_zh": "Jio Platforms IPO 开盘当日极速满额认购", "hook_en": "Reliance Industries' massive Jio Platforms IPO hit full subscription in just 100 minutes, with bids pouring in from institutions and employees alike.", "hook_zh": "印度史上最大 IPO 开门红：Jio Platforms 不到两小时即满额认购，机构抢筹踊跃。", "summary_en": "The ₹30,213 crore offering opened October 21 at ₹1,065-₹1,119 per share, aiming to repay up to ₹27,500 crore in Jio telecom debt while boosting employee morale through early salary advances for 4.2 lakh staff. Qualified institutional buyers led the charge, oversubscribing their quota early and pushing overall demand to three times by day's end. Zerodha's Nithin Kamath credited Jio's affordable data for bringing millions online and growing India's investor base from 2 crore in 2016 to over 13 crore today, marking this as the largest and fastest-subscribed IPO in recent history.", "summary_zh": "信实工业旗下 Jio Platforms 于 10 月 21 日启动约 30213 亿卢比 IPO，发行价区间每份 1065–1119 卢比，规模与认购速度均刷新纪录。锚定投资者事先承诺约 8110 亿卢比，合格机构买方份额在数分钟内超额认购逾 3 倍，散户兴趣稳步上升。募集资金主要用于还债与公司用途，估值约在 1000–1080 亿美元；申购至 10 月 23 日，预计 10 月 28 日上市。Zerodha 的 Nithin Kamath 称，Jio 推动印度数字浪潮，也让投资者基数从 2016 年约 2000 万增至逾 1.3 亿。", "body_en": "Jio Platforms IPO Fully Subscribed in 100 Minutes on Opening Day.\n\nReliance Industries' massive Jio Platforms IPO hit full subscription in just 100 minutes, with bids pouring in from institutions and employees alike.\n\nThe ₹30,213 crore offering opened October 21 at ₹1,065-₹1,119 per share, aiming to repay up to ₹27,500 crore in Jio telecom debt while boosting employee morale through early salary advances for 4.2 lakh staff.\n\nQualified institutional buyers led the charge, oversubscribing their quota early and pushing overall demand to three times by day's end. Zerodha's Nithin Kamath credited Jio's affordable data for bringing millions online and growing India's investor base from 2 crore in 2016 to over 13 crore today, marking this as the largest and fastest-subscribed IPO in recent history.", "body_zh": "Jio Platforms IPO 开盘当日极速满额认购。\n\n印度史上最大 IPO 开门红：Jio Platforms 不到两小时即满额认购，机构抢筹踊跃。\n\n信实工业旗下 Jio Platforms 于 10 月 21 日启动约 30213 亿卢比 IPO，发行价区间每份 1065–1119 卢比，规模与认购速度均刷新纪录。锚定投资者事先承诺约 8110 亿卢比，合格机构买方份额在数分钟内超额认购逾 3 倍，散户兴趣稳步上升。\n\n募集资金主要用于还债与公司用途，估值约在 1000–1080 亿美元；申购至 10 月 23 日，预计 10 月 28 日上市。Zerodha 的 Nithin Kamath 称，Jio 推动印度数字浪潮，也让投资者基数从 2016 年约 2000 万增至逾 1.3 亿。", "url": "https://x.com/i/trending/2112319265076367697", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T16:35:07.000Z"}, {"id": "2112193213931102362", "domain": "商业", "title_en": "Homebuilder Sentiment Hits 14-Year Low Amid High Rates and Costs", "title_zh": "美国建商信心跌至 14 年低点，高利率与成本承压", "hook_en": "Homebuilders are feeling the squeeze like never before, with sentiment dropping to its weakest since 2012 as mortgage rates top 7 percent.", "hook_zh": "建商感受空前挤压：抵押贷款利率站上 7%，信心跌至 2012 年以来最弱。", "summary_en": "The National Association of Home Builders/Wells Fargo Housing Market Index fell to 29 in October, missing economist expectations and marking 30 straight months below the neutral 50 level. All components declined, including buyer traffic at a dismal 18, prompting a record 43 percent of builders to cut prices by an average of 6 percent while 65 percent offered incentives like rate buydowns. Higher material, labor, and energy costs, plus rates averaging 7.40 percent, are keeping buyers away, though the discounts give some negotiating power despite strained affordability.", "summary_zh": "全美住宅建筑商协会/富国银行住房市场指数 10 月降至 29，不及经济学家预期，并连续 30 个月低于荣枯线 50。各项分项均下滑，购房客流仅 18；创纪录的 43% 建商平均降价 6%，65% 提供利率补贴等激励。材料、劳动力与能源成本走高，利率均值约 7.40%，令买家却步；虽折扣带来一定议价空间，可负担性依然紧张。", "body_en": "Homebuilder Sentiment Hits 14-Year Low Amid High Rates and Costs.\n\nHomebuilders are feeling the squeeze like never before, with sentiment dropping to its weakest since 2012 as mortgage rates top 7 percent.\n\nThe National Association of Home Builders/Wells Fargo Housing Market Index fell to 29 in October, missing economist expectations and marking 30 straight months below the neutral 50 level.\n\nAll components declined, including buyer traffic at a dismal 18, prompting a record 43 percent of builders to cut prices by an average of 6 percent while 65 percent offered incentives like rate buydowns. Higher material, labor, and energy costs, plus rates averaging 7.40 percent, are keeping buyers away, though the discounts give some negotiating power despite strained affordability.", "body_zh": "美国建商信心跌至 14 年低点，高利率与成本承压。\n\n建商感受空前挤压：抵押贷款利率站上 7%，信心跌至 2012 年以来最弱。\n\n全美住宅建筑商协会/富国银行住房市场指数 10 月降至 29，不及经济学家预期，并连续 30 个月低于荣枯线 50。\n\n各项分项均下滑，购房客流仅 18；创纪录的 43% 建商平均降价 6%，65% 提供利率补贴等激励。材料、劳动力与能源成本走高，利率均值约 7.40%，令买家却步；虽折扣带来一定议价空间，可负担性依然紧张。", "url": "https://x.com/i/trending/2112193213931102362", "category": "News", "topics": ["Business & Finance", "Real Estate"], "updated_at": "2026-10-19T21:30:31.000Z"}, {"id": "2112585549961994313", "domain": "商业", "title_en": "Hyperliquid Urges CFTC to Approve AI Compute Derivatives", "title_zh": "Hyperliquid 敦促 CFTC 批准 AI 算力衍生品", "hook_en": "AI compute power has surged as a key U.S. economic driver, but wild price swings leave data centers and developers exposed without hedging tools.", "hook_zh": "AI 算力已成美国经济关键推动力，但价格剧烈波动让数据中心与开发者在缺乏对冲工具时暴露风险。", "summary_en": "The Hyperliquid Policy Center submitted a letter to the CFTC on October 20, 2026, pushing for derivatives like perpetual futures on GPU rental prices and AI inference services to manage volatility in this vital market. They pointed to massive investments—0.8% of U.S. GDP in Q1 2026—and real examples like NVIDIA H100 rental rates dropping from $2.50-$3.19 per hour in late 2024 to $1.92-$2.00 a year later, with no way for data centers or AI firms to hedge risks since compute can't be stored. CFTC Chair Michael S. Selig has signaled support, noting America needs robust derivatives to win the AI race, and the agency recently approved its first true perpetual futures contract.", "summary_zh": "Hyperliquid 政策中心于 2026 年 10 月 20 日致函美国商品期货交易委员会（CFTC），推动推出 GPU 租金与 AI 推理服务等永续期货类衍生品，以管理这一关键市场的波动。信中指出 2026 年一季度相关投资约占美国 GDP 的 0.8%，并以英伟达 H100 租金从 2024 年末每小时约 2.50–3.19 美元降至一年后约 1.92–2.00 美元为例：算力无法储存，数据中心与 AI 公司目前几乎无法对冲。CFTC 主席迈克尔·S·塞利格已释放支持信号，称美国需强劲衍生品市场才能赢得 AI 竞赛，该机构近期亦批准了首份真正的永续期货合约。", "body_en": "Hyperliquid Urges CFTC to Approve AI Compute Derivatives.\n\nAI compute power has surged as a key U.S. economic driver, but wild price swings leave data centers and developers exposed without hedging tools.\n\nThe Hyperliquid Policy Center submitted a letter to the CFTC on October 20, 2026, pushing for derivatives like perpetual futures on GPU rental prices and AI inference services to manage volatility in this vital market. They pointed to massive investments—0.8% of U.S.\n\nGDP in Q1 2026—and real examples like NVIDIA H100 rental rates dropping from $2.50-$3.19 per hour in late 2024 to $1.92-$2.00 a year later, with no way for data centers or AI firms to hedge risks since compute can't be stored. CFTC Chair Michael S. Selig has signaled support, noting America needs robust derivatives to win the AI race, and the agency recently approved its first true perpetual futures contract.", "body_zh": "Hyperliquid 敦促 CFTC 批准 AI 算力衍生品。\n\nAI 算力已成美国经济关键推动力，但价格剧烈波动让数据中心与开发者在缺乏对冲工具时暴露风险。\n\nHyperliquid 政策中心于 2026 年 10 月 20 日致函美国商品期货交易委员会（CFTC），推动推出 GPU 租金与 AI 推理服务等永续期货类衍生品，以管理这一关键市场的波动。\n\n信中指出 2026 年一季度相关投资约占美国 GDP 的 0.8%，并以英伟达 H100 租金从 2024 年末每小时约 2.50–3.19 美元降至一年后约 1.92–2.00 美元为例：算力无法储存，数据中心与 AI 公司目前几乎无法对冲。CFTC 主席迈克尔·S·塞利格已释放支持信号，称美国需强劲衍生品市场才能赢得 AI 竞赛，该机构近期亦批准了首份真正的永续期货合约。", "url": "https://x.com/i/trending/2112585549961994313", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T16:51:10.000Z"}, {"id": "2112486884211650655", "domain": "中国", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province.\n\nThe event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112022699237310708", "domain": "中国", "title_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery", "title_zh": "良渚论坛开幕：纪念遗址发现 90 周年", "hook_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.", "hook_zh": "近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。", "summary_en": "The fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming. Under the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "summary_zh": "第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "body_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery.\n\nExperts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.\n\nThe fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming.\n\nUnder the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "body_zh": "良渚论坛开幕：纪念遗址发现 90 周年。\n\n近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。\n\n第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。\n\n首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "url": "https://x.com/i/trending/2112022699237310708", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T03:21:48.000Z"}, {"id": "2112895365657567737", "domain": "中国", "title_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike", "title_zh": "美光与台中厂达成劳资协议，罢工风险缓解", "hook_en": "Workers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.", "hook_zh": "美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。", "summary_en": "The deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days. Unions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "summary_zh": "台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "body_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike.\n\nWorkers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.\n\nThe deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days.\n\nUnions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "body_zh": "美光与台中厂达成劳资协议，罢工风险缓解。\n\n美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。\n\n台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。\n\n双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "url": "https://x.com/i/trending/2112895365657567737", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T13:20:26.000Z"}, {"id": "2111803212139569662", "domain": "中国", "title_en": "DeepSeek-V4.1-Flash Tops Coding Leaderboards at Fraction of Cost", "title_zh": "DeepSeek-V4.1-Flash 登顶编程榜，成本仅为对手约十分之一", "hook_en": "DeepSeek AI just dropped an updated open model that climbed to the top of coding leaderboards, outpacing pricier rivals while running smoothly on home setups.", "hook_zh": "DeepSeek 更新开源模型后登上编程榜前列，表现压过更贵的对手，且可在家用设备上流畅运行。", "summary_en": "Released on October 17, DeepSeek-V4.1-Flash-1017 earned the #1 spot among open models on Arena.ai's Code Arena: WebDev leaderboard with 1,670 points, ranking #12 overall ahead of Claude Opus 5 (High) and close to GPT-6 Sol (Max)—all at one-tenth the cost of competitors like Kimi K3 (Max). The 552B-parameter model, with MIT-licensed weights on Hugging Face, also hit #11 in Agent Arena, showing gains in success rates and reliability. Developers quickly optimized it for local use via Unsloth quantizations and DeepSeek's open-source DeepInfer framework, making frontier-level coding and agent performance accessible and affordable.", "summary_zh": "10 月 17 日发布的 DeepSeek-V4.1-Flash-1017 在 Arena.ai 的 Code Arena: WebDev 开源模型榜以 1670 分居首，总榜第 12，领先 Claude Opus 5（High），并接近 GPT-6 Sol（Max），成本约为 Kimi K3（Max）等竞品的十分之一。该 5520 亿参数模型以 MIT 许可权重登陆 Hugging Face，并在 Agent Arena 位列第 11，成功率与稳定性有提升。开发者迅速通过 Unsloth 量化与 DeepSeek 开源的 DeepInfer 框架做本地优化，使前沿级编程与智能体能力更易获得、也更可负担。", "body_en": "DeepSeek-V4.1-Flash Tops Coding Leaderboards at Fraction of Cost.\n\nDeepSeek AI just dropped an updated open model that climbed to the top of coding leaderboards, outpacing pricier rivals while running smoothly on home setups.\n\nReleased on October 17, DeepSeek-V4.1-Flash-1017 earned the #1 spot among open models on Arena.ai's Code Arena: WebDev leaderboard with 1,670 points, ranking #12 overall ahead of Claude Opus 5 (High) and close to GPT-6 Sol (Max)—all at one-tenth the cost of competitors like Kimi K3 (Max).\n\nThe 552B-parameter model, with MIT-licensed weights on Hugging Face, also hit #11 in Agent Arena, showing gains in success rates and reliability. Developers quickly optimized it for local use via Unsloth quantizations and DeepSeek's open-source DeepInfer framework, making frontier-level coding and agent performance accessible and affordable.", "body_zh": "DeepSeek-V4.1-Flash 登顶编程榜，成本仅为对手约十分之一。\n\nDeepSeek 更新开源模型后登上编程榜前列，表现压过更贵的对手，且可在家用设备上流畅运行。\n\n10 月 17 日发布的 DeepSeek-V4.1-Flash-1017 在 Arena.ai 的 Code Arena: WebDev 开源模型榜以 1670 分居首，总榜第 12，领先 Claude Opus 5（High），并接近 GPT-6 Sol（Max），成本约为 Kimi K3（Max）等竞品的十分之一。\n\n该 5520 亿参数模型以 MIT 许可权重登陆 Hugging Face，并在 Agent Arena 位列第 11，成功率与稳定性有提升。开发者迅速通过 Unsloth 量化与 DeepSeek 开源的 DeepInfer 框架做本地优化，使前沿级编程与智能体能力更易获得、也更可负担。", "url": "https://x.com/i/trending/2111803212139569662", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T11:32:56.000Z"}, {"id": "2112188369618784335", "domain": "中国", "title_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products", "title_zh": "美国土安全部要求民事机构清除 DeepSeek 产品", "hook_en": "The U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.", "hook_zh": "联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。", "summary_en": "Under a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services. The order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "summary_zh": "美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "body_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products.\n\nFederal agencies now face a clear directive: pull DeepSeek's Chinese AI tools from their systems to guard against data risks heading to China.\n\nThe U.S. Department of Homeland Security issued an order on October 20 requiring civilian federal agencies to remove DeepSeek products from IT systems and halt future purchases under the Federal Acquisition Supply Chain Security Act. The move addresses threats like sensitive data transfers to China, potential intelligence generation on U.S.\n\npersons, and malware risks in the models. This builds on prior limits by some agencies and states, applying broadly to civilian executive branch systems while sparing defense networks. Reactions split, with supporters praising network protection and critics noting the model's open-source nature could spur local alternatives.", "body_zh": "美国土安全部要求民事机构清除 DeepSeek 产品。\n\n联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。\n\n美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。\n\n此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:44:28.000Z"}, {"id": "2112525486228156479", "domain": "中国", "title_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks", "title_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过受限版 GPT-6 Sol", "hook_en": "In simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.", "hook_zh": "在模拟企业网络中，DeepSeek V4.1 Flash 完成的多步进攻目标多于受限版 OpenAI GPT-6 Sol，且成本更低。", "summary_en": "Vals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face. It achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "summary_zh": "Vals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，拥有百万 token 上下文，并以 MIT 许可在 Hugging Face 开源权重。其在自有评测中取得约 42.7 个目标等成绩，可在两台英伟达 DGX Spark 等设备本地运行。开发者称速度惊人，也有人担心双用途网络能力公开可得。MiniMax M3.1 Flash 在编程与视觉任务上成本更低，竞争同样激烈。", "body_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks.\n\nIn simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.\n\nVals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face.\n\nIt achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "body_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过受限版 GPT-6 Sol。\n\n在模拟企业网络中，DeepSeek V4.1 Flash 完成的多步进攻目标多于受限版 OpenAI GPT-6 Sol，且成本更低。\n\nVals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，拥有百万 token 上下文，并以 MIT 许可在 Hugging Face 开源权重。其在自有评测中取得约 42.7 个目标等成绩，可在两台英伟达 DGX Spark 等设备本地运行。\n\n开发者称速度惊人，也有人担心双用途网络能力公开可得。MiniMax M3.1 Flash 在编程与视觉任务上成本更低，竞争同样激烈。", "url": "https://x.com/i/trending/2112525486228156479", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T17:46:45.000Z"}, {"id": "2112572571275370804", "domain": "中国", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.\n\nJapan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Billboards with Scientists' Portraits in Major Cities", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Rocket scientist Qian Xuesen's giant portrait now greets shoppers in a Heze mall, replacing flashy ads with faces of national heroes.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "Since August 2026, cities like Heze, Zhengzhou, and Chongqing have filled public screens in malls, metros, and plazas with portraits of scientists such as Qian Xuesen, Yuan Longping, and Tu Youyou, complete with notes on their breakthroughs in rockets, rice, and malaria drugs. Local venues made these voluntary changes, often timed for holidays to highlight achievements in science and defense. The shift has sparked online talk about honoring innovators over celebrities and what public spaces say about a society's values.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T10:44:04.000Z"}, {"id": "2112405151768100963", "domain": "中国", "title_en": "Philippine Senators Push to Expel Chinese Ambassador Over Sea Threat", "title_zh": "菲参议员力主驱逐中国大使，因其南海「武力」表态", "hook_en": "Chinese Ambassador Jing Quan's words hung heavy: China could 'easily win' with force in the West Philippine Sea, though it prefers peace. Philippine senators fired back, demanding he be sent home.", "hook_zh": "中国大使景泉称中国若动武可在西菲律宾海「轻易取胜」，但更爱和平；菲律宾参议员要求将其遣返。", "summary_en": "Senators Risa Hontiveros and Erwin Tulfo filed resolutions urging President Marcos to declare Ambassador Jing persona non grata after his remarks, seen as a veiled threat amid China's vessel harassment and illegal fishing in Philippine waters. The Department of Foreign Affairs summoned Jing to protest, while Senator Kiko Pangilinan sharply challenged Marcos to act decisively. The Chinese Embassy hit back by listing critical lawmakers online, but Malacañang favors diplomatic channels over expulsion to avoid escalation.", "summary_zh": "参议员里萨·洪蒂维罗斯与欧文·图尔福提交决议，敦促马科斯总统宣布景泉为不受欢迎人物，认为其言论是在船只骚扰与非法捕捞背景下的含蓄威胁。外交部召见景泉抗议；参议员基科·潘吉利南尖锐要求总统果断行动。中国使馆在网上点名批评议员；马拉坎南宫则倾向以外交渠道处理，避免升级为驱逐。", "body_en": "Philippine Senators Push to Expel Chinese Ambassador Over Sea Threat.\n\nChinese Ambassador Jing Quan's words hung heavy: China could 'easily win' with force in the West Philippine Sea, though it prefers peace. Philippine senators fired back, demanding he be sent home.\n\nSenators Risa Hontiveros and Erwin Tulfo filed resolutions urging President Marcos to declare Ambassador Jing persona non grata after his remarks, seen as a veiled threat amid China's vessel harassment and illegal fishing in Philippine waters.\n\nThe Department of Foreign Affairs summoned Jing to protest, while Senator Kiko Pangilinan sharply challenged Marcos to act decisively. The Chinese Embassy hit back by listing critical lawmakers online, but Malacañang favors diplomatic channels over expulsion to avoid escalation.", "body_zh": "菲参议员力主驱逐中国大使，因其南海「武力」表态。\n\n中国大使景泉称中国若动武可在西菲律宾海「轻易取胜」，但更爱和平；菲律宾参议员要求将其遣返。\n\n参议员里萨·洪蒂维罗斯与欧文·图尔福提交决议，敦促马科斯总统宣布景泉为不受欢迎人物，认为其言论是在船只骚扰与非法捕捞背景下的含蓄威胁。\n\n外交部召见景泉抗议；参议员基科·潘吉利南尖锐要求总统果断行动。中国使馆在网上点名批评议员；马拉坎南宫则倾向以外交渠道处理，避免升级为驱逐。", "url": "https://x.com/i/trending/2112405151768100963", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T10:24:16.000Z"}, {"id": "2112161836116132305", "domain": "中国", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z"}, {"id": "2112437946263474495", "domain": "中国", "title_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal", "title_zh": "中国对美舰接近争议南沙礁盘实施跟踪监视", "hook_en": "Early Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.", "hook_zh": "周二早间，一艘美国濒海战斗舰驶入中国所称仙宾礁附近海域，北京随即派出力量实施抵近监视。", "summary_en": "China's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "summary_zh": "中国人民解放军海军指控「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾方面反驳称该舰停留在国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。此事发生在同礁附近不久前的船只碰撞之后，也正值多国在南海提出重叠领土主张之际。", "body_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal.\n\nEarly Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability.\n\nThe Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "body_zh": "中国对美舰接近争议南沙礁盘实施跟踪监视。\n\n周二早间，一艘美国濒海战斗舰驶入中国所称仙宾礁附近海域，北京随即派出力量实施抵近监视。\n\n中国人民解放军海军指控「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。\n\n菲律宾方面反驳称该舰停留在国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。此事发生在同礁附近不久前的船只碰撞之后，也正值多国在南海提出重叠领土主张之际。", "url": "https://x.com/i/trending/2112437946263474495", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T15:35:04.000Z"}, {"id": "2112579117904535807", "domain": "中国", "title_en": "Micron Funds New York Minerals Processing for AI Chip Supplies", "title_zh": "美光出资支持纽约关键矿物精炼，保障 AI 芯片原料", "hook_en": "Micron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.", "hook_zh": "美光加大在纽约本土保障 AI 存储芯片关键材料供应的力度，意在削减对海外来源的依赖，以应对需求激增。", "summary_en": "Micron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S. semiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "summary_zh": "美光科技宣布向 Indium Corporation 提供战略性资金，扩大其纽约罗马工厂对铟等关键矿物的精炼，并配套长期供货协议。此举支撑美光约 30 亿美元的美国半导体供应链投资，也回应中国在关键材料生产中的主导地位。尽管对国家安全与 AI 增长属正面一步，当日股价仍因 AI 开支、台湾相关冲击与竞争等担忧下跌约 2%–3%。", "body_en": "Micron Funds New York Minerals Processing for AI Chip Supplies.\n\nMicron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.\n\nMicron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S.\n\nsemiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "body_zh": "美光出资支持纽约关键矿物精炼，保障 AI 芯片原料。\n\n美光加大在纽约本土保障 AI 存储芯片关键材料供应的力度，意在削减对海外来源的依赖，以应对需求激增。\n\n美光科技宣布向 Indium Corporation 提供战略性资金，扩大其纽约罗马工厂对铟等关键矿物的精炼，并配套长期供货协议。\n\n此举支撑美光约 30 亿美元的美国半导体供应链投资，也回应中国在关键材料生产中的主导地位。尽管对国家安全与 AI 增长属正面一步，当日股价仍因 AI 开支、台湾相关冲击与竞争等担忧下跌约 2%–3%。", "url": "https://x.com/i/trending/2112579117904535807", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T16:26:46.000Z"}, {"id": "2112952164025028892", "domain": "国际", "title_en": "Rep. Burlison Warns Deep State Delays Could Let China or Russia Lead UAP Disclosure", "title_zh": "伯利森警告：UAP 文件拖延或让中俄抢先披露叙事", "hook_en": "Rep. Eric Burlison shared his frustration on Fox Business: a 'Deep State' is still clutching UAP files, potentially handing China or Russia the chance to break the story first.", "hook_zh": "密苏里州共和党众议员埃里克·伯利森在福克斯商业频道吐槽：所谓「深层政府」仍攥着 UAP 档案，可能把先发权拱手让给中国或俄罗斯。", "summary_en": "During an October 21 Fox Business interview, Missouri Republican Burlison highlighted resistance within agencies despite the Trump administration's PURSUE initiative, which has released over 200 UAP documents via war.gov/UFO since May 2026—the largest batch in decades. He argued that withholding more records risks rivals gaining a first-mover advantage in shaping the global narrative on unidentified anomalous phenomena, objects he's seen in briefings that 'defy logic.' Supporters see this as a push for faster transparency and whistleblower protection, while skeptics question the evidence and public release pace amid national security debates.", "summary_zh": "在 10 月 21 日采访中，伯利森称尽管特朗普政府的 PURSUE 倡议自 2026 年 5 月起已通过 war.gov/UFO 释出逾 200 份 UAP 文件——数十年来最大一批——机构内部仍有阻力。他认为继续扣留更多记录，会让对手在塑造全球不明异常现象叙事上抢得先机；他称自己在简报中见过「有违常理」的物体。支持者视之为加速透明与保护举报人的推动，怀疑者则质疑证据与国家安全背景下的公开节奏。", "body_en": "Rep. Burlison Warns Deep State Delays Could Let China or Russia Lead UAP Disclosure.\n\nRep. Eric Burlison shared his frustration on Fox Business: a 'Deep State' is still clutching UAP files, potentially handing China or Russia the chance to break the story first.\n\nDuring an October 21 Fox Business interview, Missouri Republican Burlison highlighted resistance within agencies despite the Trump administration's PURSUE initiative, which has released over 200 UAP documents via war.gov/UFO since May 2026—the largest batch in decades. He argued that withholding more records risks rivals gaining a first-mover advantage in shaping the global narrative on unidentified anomalous phenomena, objects he's seen in briefings that 'defy logic.' Supporters see this as a push for faster transparency and whistleblower protection, while skeptics question the evidence and public release pace amid national security debates.", "body_zh": "伯利森警告：UAP 文件拖延或让中俄抢先披露叙事。\n\n密苏里州共和党众议员埃里克·伯利森在福克斯商业频道吐槽：所谓「深层政府」仍攥着 UAP 档案，可能把先发权拱手让给中国或俄罗斯。\n\n在 10 月 21 日采访中，伯利森称尽管特朗普政府的 PURSUE 倡议自 2026 年 5 月起已通过 war.gov/UFO 释出逾 200 份 UAP 文件——数十年来最大一批——机构内部仍有阻力。\n\n他认为继续扣留更多记录，会让对手在塑造全球不明异常现象叙事上抢得先机；他称自己在简报中见过「有违常理」的物体。支持者视之为加速透明与保护举报人的推动，怀疑者则质疑证据与国家安全背景下的公开节奏。", "url": "https://x.com/i/trending/2112952164025028892", "category": "News", "topics": [], "updated_at": "2026-10-21T17:07:26.000Z"}, {"id": "2112296384745631848", "domain": "国际", "title_en": "France Protests Spark Debate on Russian Interference Claims", "title_zh": "法国抗议潮引发「俄方干涉」说法之争", "hook_en": "Hundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.", "hook_zh": "10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。", "summary_en": "Demonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests. Estonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "summary_zh": "全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "body_en": "France Protests Spark Debate on Russian Interference Claims.\n\nHundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.\n\nDemonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests.\n\nEstonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "body_zh": "法国抗议潮引发「俄方干涉」说法之争。\n\n10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。\n\n全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。\n\n官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "url": "https://x.com/i/trending/2112296384745631848", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:03:55.000Z"}, {"id": "2112460842902151394", "domain": "国际", "title_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters", "title_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击", "hook_en": "U.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.", "hook_zh": "美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。", "summary_en": "Rep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep. Brian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "summary_zh": "民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "body_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters.\n\nU.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.\n\nRep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep.\n\nBrian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "body_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击。\n\n美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。\n\n民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。\n\n网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "url": "https://x.com/i/trending/2112460842902151394", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T08:32:59.000Z"}, {"id": "2112501506905710732", "domain": "国际", "title_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims", "title_zh": "英波就美防长阿富汗盟友言论提出严正回应", "hook_en": "Pete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.", "hook_zh": "赫格塞思称喀布尔可见多国旗帜，但真正并肩作战者寥寥；英国与波兰领导人迅速反驳并缅怀本国阵亡者。", "summary_en": "During a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "summary_zh": "美防长 Pete Hegseth 在田纳西大学演讲称，鲜有北约盟友在阿富汗真正投入战斗，并调侃 ISAF 补丁意为“我看见美国人在打仗”。唐宁街强调英军阵亡 457 人，仅次于美国；波兰外长指出 44 名波军在加兹尼省牺牲。数据显示非美联军阵亡逾 1100 人。言论引发对盟友牺牲被低估的强烈不满。", "body_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims.\n\nPete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.\n\nDuring a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "body_zh": "英波就美防长阿富汗盟友言论提出严正回应。\n\n赫格塞思称喀布尔可见多国旗帜，但真正并肩作战者寥寥；英国与波兰领导人迅速反驳并缅怀本国阵亡者。\n\n美防长 Pete Hegseth 在田纳西大学演讲称，鲜有北约盟友在阿富汗真正投入战斗，并调侃 ISAF 补丁意为“我看见美国人在打仗”。唐宁街强调英军阵亡 457 人，仅次于美国；波兰外长指出 44 名波军在加兹尼省牺牲。\n\n数据显示非美联军阵亡逾 1100 人。言论引发对盟友牺牲被低估的强烈不满。", "url": "https://x.com/i/trending/2112501506905710732", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:10:22.000Z"}, {"id": "2112533926879125584", "domain": "国际", "title_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe", "title_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势", "hook_en": "In a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.", "hook_zh": "乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。", "summary_en": "Volodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion. Social media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "summary_zh": "泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "body_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe.\n\nIn a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.\n\nVolodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion.\n\nSocial media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "body_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势。\n\n乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。\n\n泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。\n\n社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "url": "https://x.com/i/trending/2112533926879125584", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T13:26:36.000Z"}, {"id": "2112101207397601450", "domain": "国际", "title_en": "Trump Administration Delays Patriot Missiles for Ukraine Amid Russian Attacks", "title_zh": "欧洲已付款的爱国者导弹，美方迟迟未交乌克兰", "hook_en": "As Russian missiles pound Ukrainian cities, President Zelenskyy pleads for urgent U.S. approval on Patriot interceptors that allies have already paid for and are ready to ship.", "hook_zh": "乌克兰面临弹道导弹打击，爱国者拦截弹告急，而欧洲盟友已为增援付款。", "summary_en": "Ukrainian officials report critically low Patriot interceptor stocks, vital for shielding civilians from Russian ballistic missiles and drones, while European partners await U.S. sign-off on transfers of the American-made weapons. Zelenskyy appealed directly to U.S. leaders for the missiles, early warning intelligence, and restored Starlink services, describing talks with Secretary Rubio as constructive with follow-up planned. Critics like Rep. Mike Levin and Sen. Thom Tillis blast the delays as a betrayal that weakens Ukraine's defenses, while administration officials call obstruction claims outrageous and attribute issues to technical matters. Both sides stress pursuing diplomacy to end the war, with Zelenskyy open to trilateral talks.", "summary_zh": "尽管欧洲已付款，爱国者导弹移交仍待国防部长签字；泽连斯基在俄军袭击背景下向鲁比奥国务卿强调紧迫性。", "body_en": "Trump Administration Delays Patriot Missiles for Ukraine Amid Russian Attacks.\n\nAs Russian missiles pound Ukrainian cities, President Zelenskyy pleads for urgent U.S. approval on Patriot interceptors that allies have already paid for and are ready to ship.\n\nUkrainian officials report critically low Patriot interceptor stocks, vital for shielding civilians from Russian ballistic missiles and drones, while European partners await U.S. sign-off on transfers of the American-made weapons. Zelenskyy appealed directly to U.S. leaders for the missiles, early warning intelligence, and restored Starlink services, describing talks with Secretary Rubio as constructive with follow-up planned.\n\nCritics like Rep. Mike Levin and Sen. Thom Tillis blast the delays as a betrayal that weakens Ukraine's defenses, while administration officials call obstruction claims outrageous and attribute issues to technical matters. Both sides stress pursuing diplomacy to end the war, with Zelenskyy open to trilateral talks.", "body_zh": "欧洲已付款的爱国者导弹，美方迟迟未交乌克兰。\n\n乌克兰面临弹道导弹打击，爱国者拦截弹告急，而欧洲盟友已为增援付款。\n\n尽管欧洲已付款，爱国者导弹移交仍待国防部长签字；泽连斯基在俄军袭击背景下向鲁比奥国务卿强调紧迫性。", "url": "https://x.com/i/trending/2112101207397601450", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T07:28:55.000Z"}, {"id": "2112749239679820040", "domain": "国际", "title_en": "CNN Reports Intense Internal Struggles in Trump's White House Ahead of Midterms", "title_zh": "CNN：中期选举前特朗普白宫内斗激烈", "hook_en": "A Trump ally described the White House atmosphere as brutally distrustful, saying 'You can't trust anybody here' amid fears of midterm losses.", "hook_zh": "一名特朗普盟友形容白宫氛围极度缺乏信任，称「这里谁都不能信」，并担忧中期选举失利。", "summary_en": "A CNN report cites administration officials and allies detailing power jockeying, blame-shifting, and toxicity inside the White House as Republicans brace for November's midterms. Recent signs include Kimberly Guilfoyle's ouster as ambassador to Greece and probes into disputes over Kennedy Center funding involving Alina Habba Mildon and Ric Grenell. White House spokesman Davis Ingle dismissed the claims as baseless speculation, insisting Trump stays focused on securing congressional majorities. Other outlets like The Washington Post echo themes of aides positioning for post-election roles.", "summary_zh": "CNN 援引政府官员与盟友，描述共和党备战 11 月中期之际白宫内权力争斗、甩锅与紧张气氛。近期迹象包括金伯利·吉尔福伊勒被免去驻希腊大使，以及围绕肯尼迪中心资金、牵涉阿丽娜·哈巴·米尔登与里克·格内尔的争议调查。白宫发言人戴维斯·英格尔称相关说法为无根据猜测，并称特朗普专注于保住国会多数。《华盛顿邮报》等亦提到助手们为选后角色卡位。", "body_en": "CNN Reports Intense Internal Struggles in Trump's White House Ahead of Midterms.\n\nA Trump ally described the White House atmosphere as brutally distrustful, saying 'You can't trust anybody here' amid fears of midterm losses.\n\nA CNN report cites administration officials and allies detailing power jockeying, blame-shifting, and toxicity inside the White House as Republicans brace for November's midterms. Recent signs include Kimberly Guilfoyle's ouster as ambassador to Greece and probes into disputes over Kennedy Center funding involving Alina Habba Mildon and Ric Grenell.\n\nWhite House spokesman Davis Ingle dismissed the claims as baseless speculation, insisting Trump stays focused on securing congressional majorities. Other outlets like The Washington Post echo themes of aides positioning for post-election roles.", "body_zh": "CNN：中期选举前特朗普白宫内斗激烈。\n\n一名特朗普盟友形容白宫氛围极度缺乏信任，称「这里谁都不能信」，并担忧中期选举失利。\n\nCNN 援引政府官员与盟友，描述共和党备战 11 月中期之际白宫内权力争斗、甩锅与紧张气氛。近期迹象包括金伯利·吉尔福伊勒被免去驻希腊大使，以及围绕肯尼迪中心资金、牵涉阿丽娜·哈巴·米尔登与里克·格内尔的争议调查。\n\n白宫发言人戴维斯·英格尔称相关说法为无根据猜测，并称特朗普专注于保住国会多数。《华盛顿邮报》等亦提到助手们为选后角色卡位。", "url": "https://x.com/i/trending/2112749239679820040", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T03:38:52.000Z"}, {"id": "2112384299999850805", "domain": "国际", "title_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally", "title_zh": "特朗普在堪萨斯集会警告或退出北约", "hook_en": "Thousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.", "hook_zh": "数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。", "summary_en": "At a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate. He criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "summary_zh": "在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "body_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally.\n\nThousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.\n\nAt a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate.\n\nHe criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "body_zh": "特朗普在堪萨斯集会警告或退出北约。\n\n数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。\n\n在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。\n\n他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "url": "https://x.com/i/trending/2112384299999850805", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T21:20:55.000Z"}, {"id": "2111568548271440224", "domain": "国际", "title_en": "Putin Proposes Trump-Xi Summit to End Ukraine War, Excluding Zelenskyy", "title_zh": "普京提议特朗普—习近平三方峰会谈乌克兰，排除泽连斯基", "hook_en": "Vladimir Putin reached out to Donald Trump with a bold idea: a three-way summit with Xi Jinping to halt the Ukraine war, leaving Zelenskyy on the outside.", "hook_zh": "弗拉基米尔·普京向唐纳德·特朗普抛出大胆构想：与习近平举行三方峰会以停止乌克兰战争，把泽连斯基排除在外。", "summary_en": "The proposal came from an October 9 phone call between Putin and Trump, which also led to a deal for U.S. purchases of Russian diesel fuel. Trump expressed openness, criticizing Zelenskyy for prolonging the conflict amid heavy funding from Europe and past U.S. aid, while noting Ukrainian strikes on Russian refineries hurt global energy and American interests. Supporters see it as a path to peace; critics, including Ukrainian officials and experts like Michael McFaul, warn it rewards aggression and sidelines Kyiv. The potential meeting could happen at the APEC summit in Shenzhen next month.", "summary_zh": "提议源自 10 月 9 日普京与特朗普通话，同一次通话还促成美方采购俄柴油的交易。特朗普表示开放，批评泽连斯基在欧洲与过去美援大量投入背景下拖延冲突，并称乌方打击俄炼油厂损害全球能源与美国利益。支持者视其为和平路径；批评者包括乌克兰官员与迈克尔·麦克福尔等专家，警告这会奖励侵略并边缘化基辅。潜在会面或于下月深圳 APEC 峰会期间举行。", "body_en": "Putin Proposes Trump-Xi Summit to End Ukraine War, Excluding Zelenskyy.\n\nVladimir Putin reached out to Donald Trump with a bold idea: a three-way summit with Xi Jinping to halt the Ukraine war, leaving Zelenskyy on the outside.\n\nThe proposal came from an October 9 phone call between Putin and Trump, which also led to a deal for U.S. purchases of Russian diesel fuel. Trump expressed openness, criticizing Zelenskyy for prolonging the conflict amid heavy funding from Europe and past U.S.\n\naid, while noting Ukrainian strikes on Russian refineries hurt global energy and American interests. Supporters see it as a path to peace; critics, including Ukrainian officials and experts like Michael McFaul, warn it rewards aggression and sidelines Kyiv. The potential meeting could happen at the APEC summit in Shenzhen next month.", "body_zh": "普京提议特朗普—习近平三方峰会谈乌克兰，排除泽连斯基。\n\n弗拉基米尔·普京向唐纳德·特朗普抛出大胆构想：与习近平举行三方峰会以停止乌克兰战争，把泽连斯基排除在外。\n\n提议源自 10 月 9 日普京与特朗普通话，同一次通话还促成美方采购俄柴油的交易。特朗普表示开放，批评泽连斯基在欧洲与过去美援大量投入背景下拖延冲突，并称乌方打击俄炼油厂损害全球能源与美国利益。\n\n支持者视其为和平路径；批评者包括乌克兰官员与迈克尔·麦克福尔等专家，警告这会奖励侵略并边缘化基辅。潜在会面或于下月深圳 APEC 峰会期间举行。", "url": "https://x.com/i/trending/2111568548271440224", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-19T19:30:26.000Z"}, {"id": "2112302146825949613", "domain": "国际", "title_en": "Republican Lawmakers Criticize Trump Waiver of Russia Sanctions", "title_zh": "共和党议员批评特朗普豁免对俄制裁条款", "hook_en": "Congressman Max Miller, representing a district with thousands of Ukrainian Americans, called out the Trump administration for waiving sanctions meant to punish Russia over Ukraine.", "hook_zh": "选区有大量乌克兰裔选民的众议员马克斯·米勒，公开批评特朗普政府豁免本用于惩罚俄罗斯侵乌的制裁条款。", "summary_en": "Reps. Max Miller of Ohio and Jeff Hurd of Colorado sharply criticized the Trump administration's decision to waive key provisions of the bipartisan Lindsey O. Graham Sanctioning Russia and Iran Act of 2026, which Congress passed in September to cut Russia's war funding through tariffs and economic measures. Trump cited national interests like lowering U.S. energy prices and advancing peace talks, but the lawmakers argued it eases pressure on Moscow amid its ongoing attacks on Ukraine without real concessions. The move has sparked mixed reactions, with some praising the critics and others prioritizing domestic issues, highlighting GOP tensions over Ukraine support and energy costs ahead of midterms.", "summary_zh": "俄亥俄州众议员马克斯·米勒与科罗拉多州杰夫·赫德，尖锐批评特朗普政府豁免两党《2026 年林赛·格雷厄姆制裁俄罗斯与伊朗法》关键条款；该法于 9 月通过，拟以关税与经济手段削弱俄战争资金。特朗普以降低美国能源价格、推动和谈等「国家利益」为由，议员则认为在莫斯科未作实质让步、仍持续攻乌之际放松压力。反应分化：有人赞赏批评声音，有人更看重国内议题，凸显中期选举前共和党内在挺乌与能源成本上的张力。", "body_en": "Republican Lawmakers Criticize Trump Waiver of Russia Sanctions.\n\nCongressman Max Miller, representing a district with thousands of Ukrainian Americans, called out the Trump administration for waiving sanctions meant to punish Russia over Ukraine.\n\nReps. Max Miller of Ohio and Jeff Hurd of Colorado sharply criticized the Trump administration's decision to waive key provisions of the bipartisan Lindsey O. Graham Sanctioning Russia and Iran Act of 2026, which Congress passed in September to cut Russia's war funding through tariffs and economic measures.\n\nTrump cited national interests like lowering U.S. energy prices and advancing peace talks, but the lawmakers argued it eases pressure on Moscow amid its ongoing attacks on Ukraine without real concessions. The move has sparked mixed reactions, with some praising the critics and others prioritizing domestic issues, highlighting GOP tensions over Ukraine support and energy costs ahead of midterms.", "body_zh": "共和党议员批评特朗普豁免对俄制裁条款。\n\n选区有大量乌克兰裔选民的众议员马克斯·米勒，公开批评特朗普政府豁免本用于惩罚俄罗斯侵乌的制裁条款。\n\n俄亥俄州众议员马克斯·米勒与科罗拉多州杰夫·赫德，尖锐批评特朗普政府豁免两党《2026 年林赛·格雷厄姆制裁俄罗斯与伊朗法》关键条款；该法于 9 月通过，拟以关税与经济手段削弱俄战争资金。\n\n特朗普以降低美国能源价格、推动和谈等「国家利益」为由，议员则认为在莫斯科未作实质让步、仍持续攻乌之际放松压力。反应分化：有人赞赏批评声音，有人更看重国内议题，凸显中期选举前共和党内在挺乌与能源成本上的张力。", "url": "https://x.com/i/trending/2112302146825949613", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-19T22:08:39.000Z"}, {"id": "2112660061600309523", "domain": "国际", "title_en": "National Security Officials Quietly Prep States for Potential Midterm Interference", "title_zh": "美安全官员低调向多州通报中期选举风险", "hook_en": "A handful of U.S. national security veterans have spent months huddling with governors and lawmakers, mapping out responses to possible federal moves at polling places.", "hook_zh": "一小群国防部相关官员数月来悄然咨询约 10 个州的州长与议员，为投票站出现联邦部队等情景做准备。", "summary_en": "About 10 current and former Defense Department officials, some with experience countering authoritarianism abroad, have consulted with leaders in roughly 10 states on scenarios like federal troops or immigration agents at polls or fraud challenges. Speaking anonymously to avoid retaliation, they stress their nonpartisan work stems from concerns over federal overreach, targeting states with tight races that could decide Congress. The Washington Post report has drawn accusations of 'deep state' plotting from critics, while supporters see it as prudent election planning amid rising distrust between the Trump administration and parts of the security community.", "summary_zh": "约 10 名现任与前任官员，向两党选举官员与国会议员通报特朗普政府可能采取的行动，例如移民执法人员出现在投票站，或借舞弊指控试图否定结果。重点放在可能左右国会控制权的摇摆州；参与者称关切选举完整性，并因担心报复而匿名发声。反应尖锐对立：有人视之为必要预案，也有人质疑这群非选举产生人士的秘密角色，以及联邦与州权之间的紧张。", "body_en": "National Security Officials Quietly Prep States for Potential Midterm Interference.\n\nA handful of U.S. national security veterans have spent months huddling with governors and lawmakers, mapping out responses to possible federal moves at polling places.\n\nAbout 10 current and former Defense Department officials, some with experience countering authoritarianism abroad, have consulted with leaders in roughly 10 states on scenarios like federal troops or immigration agents at polls or fraud challenges.\n\nSpeaking anonymously to avoid retaliation, they stress their nonpartisan work stems from concerns over federal overreach, targeting states with tight races that could decide Congress. The Washington Post report has drawn accusations of 'deep state' plotting from critics, while supporters see it as prudent election planning amid rising distrust between the Trump administration and parts of the security community.", "body_zh": "美安全官员低调向多州通报中期选举风险。\n\n一小群国防部相关官员数月来悄然咨询约 10 个州的州长与议员，为投票站出现联邦部队等情景做准备。\n\n约 10 名现任与前任官员，向两党选举官员与国会议员通报特朗普政府可能采取的行动，例如移民执法人员出现在投票站，或借舞弊指控试图否定结果。\n\n重点放在可能左右国会控制权的摇摆州；参与者称关切选举完整性，并因担心报复而匿名发声。反应尖锐对立：有人视之为必要预案，也有人质疑这群非选举产生人士的秘密角色，以及联邦与州权之间的紧张。", "url": "https://x.com/i/trending/2112660061600309523", "category": "News", "topics": ["Elections"], "updated_at": "2026-10-21T17:07:44.000Z"}, {"id": "2112891432692502750", "domain": "国际", "title_en": "Zelenskyy Open to Freezing Ukraine War Along Current Lines", "title_zh": "泽连斯基表态可接受沿现有战线冻结乌克兰战事", "hook_en": "In a live Fox News interview, Ukrainian President Volodymyr Zelenskyy said yes to halting the fighting right where frontlines stand today. He called it the real path to end the war and stop the killing.", "hook_zh": "乌克兰总统泽连斯基在福克斯新闻直播中表示，愿意就地停火——前线停在哪里，就停在哪里；他称这是结束战争、停止杀戮的现实路径。", "summary_en": "Zelenskyy appeared on Fox & Friends and agreed to freeze the conflict, retaining about 75% of Ukraine's territory, as a minimum step before seeking security guarantees from the U.S. and Europe. The remarks came amid U.S. envoy Steve Witkoff's meetings with Zelenskyy in Oslo and Putin in St. Petersburg, where a detained American was released. Zelenskyy also highlighted bringing home 9.5 million displaced Ukrainians to rebuild, while reactions ranged from celebrations of a breakthrough to notes that his stance aligns with prior statements. Broader talks continue, with Zelenskyy stressing direct Ukrainian involvement and lasting peace security.", "summary_zh": "泽连斯基登上《Fox & Friends》节目，同意冻结冲突并保留约 75% 乌克兰领土，以此作为向美欧寻求安全保证前的最低步骤。表态之际，美国特使史蒂夫·维特科夫正分别在奥斯陆会见泽连斯基、在圣彼得堡会见普京，期间一名被扣押的美国人获释。泽连斯基还强调要接回约 950 万流离失所者参与重建；外界反应从欢呼突破到指出其立场与此前表述一脉相承不等。更广泛谈判仍在继续，他强调乌方必须直接参与并争取持久和平保障。", "body_en": "Zelenskyy Open to Freezing Ukraine War Along Current Lines.\n\nIn a live Fox News interview, Ukrainian President Volodymyr Zelenskyy said yes to halting the fighting right where frontlines stand today. He called it the real path to end the war and stop the killing.\n\nZelenskyy appeared on Fox & Friends and agreed to freeze the conflict, retaining about 75% of Ukraine's territory, as a minimum step before seeking security guarantees from the U.S. and Europe. The remarks came amid U.S.\n\nenvoy Steve Witkoff's meetings with Zelenskyy in Oslo and Putin in St. Petersburg, where a detained American was released. Zelenskyy also highlighted bringing home 9.5 million displaced Ukrainians to rebuild, while reactions ranged from celebrations of a breakthrough to notes that his stance aligns with prior statements. Broader talks continue, with Zelenskyy stressing direct Ukrainian involvement and lasting peace security.", "body_zh": "泽连斯基表态可接受沿现有战线冻结乌克兰战事。\n\n乌克兰总统泽连斯基在福克斯新闻直播中表示，愿意就地停火——前线停在哪里，就停在哪里；他称这是结束战争、停止杀戮的现实路径。\n\n泽连斯基登上《Fox & Friends》节目，同意冻结冲突并保留约 75% 乌克兰领土，以此作为向美欧寻求安全保证前的最低步骤。表态之际，美国特使史蒂夫·维特科夫正分别在奥斯陆会见泽连斯基、在圣彼得堡会见普京，期间一名被扣押的美国人获释。\n\n泽连斯基还强调要接回约 950 万流离失所者参与重建；外界反应从欢呼突破到指出其立场与此前表述一脉相承不等。更广泛谈判仍在继续，他强调乌方必须直接参与并争取持久和平保障。", "url": "https://x.com/i/trending/2112891432692502750", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:07:52.000Z"}, {"id": "2112905935983382837", "domain": "国际", "title_en": "Netanyahu Pushed Iran Strikes, Trump Blocked Before U.S. Elections", "title_zh": "内塔尼亚胡力推打击伊朗，特朗普因美国大选叫停", "hook_en": "Israeli Prime Minister Benjamin Netanyahu readied major strikes on Iran's nuclear sites and power plants for mid-October. U.S. President Donald Trump stepped in to halt the plan, wary of election fallout.", "hook_zh": "以色列总理本雅明·内塔尼亚胡曾准备在 10 月中旬对伊朗核设施与电厂发动大规模打击；美国总统唐纳德·特朗普介入叫停，担心影响选情。", "summary_en": "Israel prepared a multi-day bombing campaign targeting nuclear facilities, regime sites, and civilian infrastructure like electricity plants for the weekend of October 10, but Trump vetoed it to prevent energy price spikes ahead of November 3 midterms. Netanyahu, eyeing Israel's October 27 election, rallied support by vowing to overthrow Iran's regime, while Tehran warned of unlimited retaliation. Analysts see renewed strikes as possible soon, even without U.S. backing, amid ongoing threats from both sides. Separately, Donald Trump Jr. privately urged his father against deeper U.S. involvement in the conflict.", "summary_zh": "以色列原计划在 10 月 10 日那个周末展开多日轰炸，目标涵盖核设施、政权据点及电厂等民用基础设施，但特朗普为避免 11 月 3 日中期选举前能源价格飙升而予以否决。内塔尼亚胡着眼以色列 10 月 27 日选举，以誓言推翻伊朗政权凝聚支持；德黑兰则警告将「无限报复」。分析人士认为即便没有美方背书，打击仍可能很快再起，双方威胁不断。另有消息称小唐纳德·特朗普私下劝父亲勿更深卷入冲突。", "body_en": "Netanyahu Pushed Iran Strikes, Trump Blocked Before U.S. Elections.\n\nIsraeli Prime Minister Benjamin Netanyahu readied major strikes on Iran's nuclear sites and power plants for mid-October. U.S. President Donald Trump stepped in to halt the plan, wary of election fallout.\n\nIsrael prepared a multi-day bombing campaign targeting nuclear facilities, regime sites, and civilian infrastructure like electricity plants for the weekend of October 10, but Trump vetoed it to prevent energy price spikes ahead of November 3 midterms. Netanyahu, eyeing Israel's October 27 election, rallied support by vowing to overthrow Iran's regime, while Tehran warned of unlimited retaliation. Analysts see renewed strikes as possible soon, even without U.S.\n\nbacking, amid ongoing threats from both sides. Separately, Donald Trump Jr. privately urged his father against deeper U.S. involvement in the conflict.", "body_zh": "内塔尼亚胡力推打击伊朗，特朗普因美国大选叫停。\n\n以色列总理本雅明·内塔尼亚胡曾准备在 10 月中旬对伊朗核设施与电厂发动大规模打击；美国总统唐纳德·特朗普介入叫停，担心影响选情。\n\n以色列原计划在 10 月 10 日那个周末展开多日轰炸，目标涵盖核设施、政权据点及电厂等民用基础设施，但特朗普为避免 11 月 3 日中期选举前能源价格飙升而予以否决。内塔尼亚胡着眼以色列 10 月 27 日选举，以誓言推翻伊朗政权凝聚支持；德黑兰则警告将「无限报复」。\n\n分析人士认为即便没有美方背书，打击仍可能很快再起，双方威胁不断。另有消息称小唐纳德·特朗普私下劝父亲勿更深卷入冲突。", "url": "https://x.com/i/trending/2112905935983382837", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T16:44:41.000Z"}, {"id": "2112773061082767722", "domain": "国际", "title_en": "Putin Ordered Sabotage Campaign Against NATO, U.S. Intel Assesses", "title_zh": "美情报称普京下令加大对北约欧洲的破坏行动", "hook_en": "A drone packed with explosives struck a cargo plane at Germany's Leipzig-Halle Airport in August, but mercifully failed to detonate. U.S. intelligence now pins it on a personal order from Putin to ramp up covert attacks on NATO nations.", "hook_zh": "今年 8 月一架装有爆炸物的无人机袭击德国莱比锡机场一架乌克兰货机但未起爆，被指属于更广泛隐蔽行动的一部分。", "summary_en": "The Wall Street Journal investigation reveals Russian President Vladimir Putin directed the GRU military intelligence unit to intensify sabotage against NATO countries, targeting military aid shipments to Ukraine, infrastructure, and shipping to weaken European support. The Leipzig plot involved three drones aimed at an Antonov aircraft; one hit but didn't explode, averting disaster. German Chancellor Friedrich Merz warned of Russia's societal threat, noting mass casualties there could have triggered NATO's Article 5. Berlin blamed Moscow publicly, raised sabotage alerts, while Russia denies involvement.", "summary_zh": "美方情报称，因乌克兰和谈停滞及基辅深远打击，普京直接下令显著加强对欧洲北约国家的破坏活动。莱比锡事件被指向经塞尔维亚运送爆炸物的俄军情报单位，目标涉及军援；克里姆林宫后据称通过后门警告德国还将有更多袭击。德国已将军事破坏威胁调至“显著”，并讨论若造成伤亡是否触及北约第五条。俄方否认，北约仍在评估应对。", "body_en": "Putin Ordered Sabotage Campaign Against NATO, U.S. Intel Assesses.\n\nA drone packed with explosives struck a cargo plane at Germany's Leipzig-Halle Airport in August, but mercifully failed to detonate. U.S. intelligence now pins it on a personal order from Putin to ramp up covert attacks on NATO nations.\n\nThe Wall Street Journal investigation reveals Russian President Vladimir Putin directed the GRU military intelligence unit to intensify sabotage against NATO countries, targeting military aid shipments to Ukraine, infrastructure, and shipping to weaken European support. The Leipzig plot involved three drones aimed at an Antonov aircraft; one hit but didn't explode, averting disaster.\n\nGerman Chancellor Friedrich Merz warned of Russia's societal threat, noting mass casualties there could have triggered NATO's Article 5. Berlin blamed Moscow publicly, raised sabotage alerts, while Russia denies involvement.", "body_zh": "美情报称普京下令加大对北约欧洲的破坏行动。\n\n今年 8 月一架装有爆炸物的无人机袭击德国莱比锡机场一架乌克兰货机但未起爆，被指属于更广泛隐蔽行动的一部分。\n\n美方情报称，因乌克兰和谈停滞及基辅深远打击，普京直接下令显著加强对欧洲北约国家的破坏活动。莱比锡事件被指向经塞尔维亚运送爆炸物的俄军情报单位，目标涉及军援；克里姆林宫后据称通过后门警告德国还将有更多袭击。\n\n德国已将军事破坏威胁调至“显著”，并讨论若造成伤亡是否触及北约第五条。俄方否认，北约仍在评估应对。", "url": "https://x.com/i/trending/2112773061082767722", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T14:41:42.000Z"}, {"id": "2112653362286284987", "domain": "国际", "title_en": "Elbit Systems Acquires Canadian Underwater Robotics Firm ISE", "title_zh": "埃尔比特系统收购加拿大水下机器人公司 ISE", "hook_en": "Bright yellow submersibles glide through coastal waters, now part of a larger Israeli defense portfolio after Elbit Systems finalized its purchase of British Columbia's ISE.", "hook_zh": "鲜黄色潜水器划过近海水域——在埃尔比特系统完成收购不列颠哥伦比亚省 ISE 后，它们已并入更大的以色列防务版图。", "summary_en": "Elbit Systems completed the acquisition of International Submarine Engineering Ltd. (ISE) around October 20, 2026, gaining expertise in autonomous underwater vehicles, remotely operated vehicles, and subsea robotics delivered to over 20 countries. The deal bolsters Elbit's capabilities in underwater surveillance, mine countermeasures, and anti-submarine warfare. Canadian supporters like the Centre for Israel and Jewish Affairs praise it for aligning with national defence strategy and creating jobs, while critics including NDP leader Avi Lewis call for cancellation due to Elbit's alleged role in the Gaza conflict and raise concerns over foreign ownership of defence tech.", "summary_zh": "埃尔比特系统约于 2026 年 10 月 20 日完成对国际潜艇工程公司（ISE）的收购，获得自主水下航行器、遥控潜水器与海底机器人专长，相关装备已交付逾 20 国。交易强化其水下监视、扫雷与反潜作战能力。加拿大以色列与犹太事务中心等支持者称其契合国防战略并创造就业；新民主党领袖阿维·刘易斯等批评者则因埃尔比特据称在加沙冲突中的角色呼吁取消交易，并担忧国防技术的外资所有权。", "body_en": "Elbit Systems Acquires Canadian Underwater Robotics Firm ISE.\n\nBright yellow submersibles glide through coastal waters, now part of a larger Israeli defense portfolio after Elbit Systems finalized its purchase of British Columbia's ISE.\n\nElbit Systems completed the acquisition of International Submarine Engineering Ltd. (ISE) around October 20, 2026, gaining expertise in autonomous underwater vehicles, remotely operated vehicles, and subsea robotics delivered to over 20 countries.\n\nThe deal bolsters Elbit's capabilities in underwater surveillance, mine countermeasures, and anti-submarine warfare. Canadian supporters like the Centre for Israel and Jewish Affairs praise it for aligning with national defence strategy and creating jobs, while critics including NDP leader Avi Lewis call for cancellation due to Elbit's alleged role in the Gaza conflict and raise concerns over foreign ownership of defence tech.", "body_zh": "埃尔比特系统收购加拿大水下机器人公司 ISE。\n\n鲜黄色潜水器划过近海水域——在埃尔比特系统完成收购不列颠哥伦比亚省 ISE 后，它们已并入更大的以色列防务版图。\n\n埃尔比特系统约于 2026 年 10 月 20 日完成对国际潜艇工程公司（ISE）的收购，获得自主水下航行器、遥控潜水器与海底机器人专长，相关装备已交付逾 20 国。\n\n交易强化其水下监视、扫雷与反潜作战能力。加拿大以色列与犹太事务中心等支持者称其契合国防战略并创造就业；新民主党领袖阿维·刘易斯等批评者则因埃尔比特据称在加沙冲突中的角色呼吁取消交易，并担忧国防技术的外资所有权。", "url": "https://x.com/i/trending/2112653362286284987", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T21:20:14.000Z"}, {"id": "2112588449140355241", "domain": "体育", "title_en": "LA Bar Group Hedges Dodgers Loss with $60K Bet, Doubles Money", "title_zh": "洛杉矶酒吧联盟押注道奇出局，6 万美元翻倍对冲空场损失", "hook_en": "When the Dodgers fell to the Brewers in the NLCS, a group of 25 bars near the stadium didn't sweat the empty seats—their clever $60,000 bet paid out $120,000 to cover the shortfall.", "hook_zh": "道奇在联盟冠军赛不敌酿酒人后，球场附近 25 家酒吧并未慌张——他们聪明的 6 万美元押注赔出 12 万，弥补少赛带来的缺口。", "summary_en": "The Los Angeles hospitality group bet on Kalshi that the Dodgers wouldn't reach the World Series, creating a perfect hedge against lost revenue from an early playoff exit. The wager doubled their money when the team lost, matching the extra business they expected from more games. This smart move highlights how prediction markets let businesses manage sports risks like custom insurance, with observers calling it 'pretty damn clever' and a win-win for crowd-dependent spots.", "summary_zh": "洛杉矶餐饮集团在 Kalshi 上押注道奇无法进世界大赛，完美对冲季后赛早早出局的营收损失。球队落败后赌注翻倍，大致匹配若多打几场本可多赚的生意。此举凸显预测市场可让依赖客流的商家像买定制保险一样管理体育风险，观察者称「相当聪明」、近乎双赢。", "body_en": "LA Bar Group Hedges Dodgers Loss with $60K Bet, Doubles Money.\n\nWhen the Dodgers fell to the Brewers in the NLCS, a group of 25 bars near the stadium didn't sweat the empty seats—their clever $60,000 bet paid out $120,000 to cover the shortfall.\n\nThe Los Angeles hospitality group bet on Kalshi that the Dodgers wouldn't reach the World Series, creating a perfect hedge against lost revenue from an early playoff exit.\n\nThe wager doubled their money when the team lost, matching the extra business they expected from more games. This smart move highlights how prediction markets let businesses manage sports risks like custom insurance, with observers calling it 'pretty damn clever' and a win-win for crowd-dependent spots.", "body_zh": "洛杉矶酒吧联盟押注道奇出局，6 万美元翻倍对冲空场损失。\n\n道奇在联盟冠军赛不敌酿酒人后，球场附近 25 家酒吧并未慌张——他们聪明的 6 万美元押注赔出 12 万，弥补少赛带来的缺口。\n\n洛杉矶餐饮集团在 Kalshi 上押注道奇无法进世界大赛，完美对冲季后赛早早出局的营收损失。\n\n球队落败后赌注翻倍，大致匹配若多打几场本可多赚的生意。此举凸显预测市场可让依赖客流的商家像买定制保险一样管理体育风险，观察者称「相当聪明」、近乎双赢。", "url": "https://x.com/i/trending/2112588449140355241", "category": "News", "topics": ["Baseball"], "updated_at": "2026-10-21T01:55:22.000Z"}, {"id": "2112637280108335380", "domain": "体育", "title_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley", "title_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌", "hook_en": "Larry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.", "hook_zh": "拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。", "summary_en": "During the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties. A middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "summary_zh": "休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "body_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley.\n\nLarry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.\n\nDuring the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties.\n\nA middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "body_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌。\n\n拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。\n\n休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。\n\n史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "url": "https://x.com/i/trending/2112637280108335380", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T20:16:29.000Z"}, {"id": "2112363184577191956", "domain": "体育", "title_en": "NFL Pushes Ahead with Paris Game Amid French Protests", "title_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛", "hook_en": "As riots flare across parts of France, the NFL stays committed to its first regular-season game in Paris, with Steelers linebacker TJ Watt's wife openly questioning the call.", "hook_zh": "巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。", "summary_en": "The Pittsburgh Steelers face the New Orleans Saints this Sunday at Stade de France in Saint-Denis, a key step in the league's international push, despite weeks of protests over school conditions and living costs that turned violent with fires, looting, and over 1,000 arrests. Commissioner Roger Goodell insists the matchup is safe, with protests mostly peaceful and the stadium outside central hotspots, while the league ramps up security in coordination with French authorities and the U.S. State Department. Fans mix excitement with worry, as Dani Watt posted on Instagram, 'Tell me how this makes sense???', but executives confirm no plans to cancel the historic event.", "summary_zh": "匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "body_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest.\n\nAs riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.\n\nThe Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews. League officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S.\n\nState Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "body_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛。\n\n巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。\n\n匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。\n\n圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "url": "https://x.com/i/trending/2112363184577191956", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T16:57:57.000Z"}, {"id": "2112620322600223204", "domain": "体育", "title_en": "FIFA Explores Himalaya Cup for Regional South Asian Football", "title_zh": "国际足联探讨创办南亚「喜马拉雅杯」", "hook_en": "Gianni Infantino donned traditional Bhutanese attire alongside local players and officials, sparking early talks on a new tournament to boost football in the Himalayas.", "hook_zh": "詹尼·因凡蒂诺身着不丹传统服饰，与当地球员和官员合影，并就提升喜马拉雅地区足球的新赛事展开早期讨论。", "summary_en": "During his recent visit to Bhutan, FIFA President Gianni Infantino discussed football development, leading to proposals for a Himalaya Cup involving nations like Nepal, Bhutan, India, Pakistan, China-Tibet, Maldives, and Sri Lanka. The tournament aims to provide systematic growth opportunities for South Asian football, building on FIFA's support for infrastructure and youth programs in Bhutan, including visits to Changlimithang Stadium and meetings with the prime minister and U-15 team. While fans show enthusiasm for more matches, questions linger about its fit with events like the SAFF Championship, and no final decision has been made as talks continue.", "summary_zh": "国际足联主席詹尼·因凡蒂诺近日访问不丹，讨论足球发展，并催生「喜马拉雅杯」构想，潜在参与方包括尼泊尔、不丹、印度、巴基斯坦、中国西藏、马尔代夫与斯里兰卡等。赛事旨在为南亚足球提供系统性成长机会，并建立在国际足联对不丹基建与青训支持之上，包括走访昌利米塘体育场、会见总理与 U-15 队。球迷对更多比赛表示期待，但与 SAFF 锦标赛等现有赛事如何衔接仍存疑问；会谈仍在继续，尚未最终拍板。", "body_en": "FIFA Explores Himalaya Cup for Regional South Asian Football.\n\nGianni Infantino donned traditional Bhutanese attire alongside local players and officials, sparking early talks on a new tournament to boost football in the Himalayas.\n\nDuring his recent visit to Bhutan, FIFA President Gianni Infantino discussed football development, leading to proposals for a Himalaya Cup involving nations like Nepal, Bhutan, India, Pakistan, China-Tibet, Maldives, and Sri Lanka.\n\nThe tournament aims to provide systematic growth opportunities for South Asian football, building on FIFA's support for infrastructure and youth programs in Bhutan, including visits to Changlimithang Stadium and meetings with the prime minister and U-15 team. While fans show enthusiasm for more matches, questions linger about its fit with events like the SAFF Championship, and no final decision has been made as talks continue.", "body_zh": "国际足联探讨创办南亚「喜马拉雅杯」。\n\n詹尼·因凡蒂诺身着不丹传统服饰，与当地球员和官员合影，并就提升喜马拉雅地区足球的新赛事展开早期讨论。\n\n国际足联主席詹尼·因凡蒂诺近日访问不丹，讨论足球发展，并催生「喜马拉雅杯」构想，潜在参与方包括尼泊尔、不丹、印度、巴基斯坦、中国西藏、马尔代夫与斯里兰卡等。\n\n赛事旨在为南亚足球提供系统性成长机会，并建立在国际足联对不丹基建与青训支持之上，包括走访昌利米塘体育场、会见总理与 U-15 队。球迷对更多比赛表示期待，但与 SAFF 锦标赛等现有赛事如何衔接仍存疑问；会谈仍在继续，尚未最终拍板。", "url": "https://x.com/i/trending/2112620322600223204", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-20T19:09:02.000Z"}, {"id": "2112933588320878832", "domain": "体育", "title_en": "Carlton Fisk Waves Home Run Fair in Epic 1975 World Series Game 6", "title_zh": "卡尔顿·菲斯克挥臂「助攻」本垒打：1975 年世界大赛经典第六战", "hook_en": "Carlton Fisk leaped into the night air at Fenway Park, waving his arms wildly to coax his deep fly ball fair off the foul pole. That raw, joyous moment in the 12th inning sealed a 7-6 walk-off win for the Red Sox.", "hook_zh": "卡尔顿·菲斯克在芬威球场跃起，双手狂挥，把深远飞球「招」进界内击中标杆；第十二局这一幕定格红袜 7–6 再见胜。", "summary_en": "On October 21, 1975, Boston catcher Carlton Fisk led off the bottom of the 12th in Game 6 of the World Series against the Cincinnati Reds. He smashed a 1-0 sinker from Pat Darcy that hugged the left-field foul pole after Fisk's frantic urging, forcing a Game 7. Earlier, pinch-hitter Bernie Carbo's three-run homer in the eighth had tied it at 6-6. The NBC camera inside the Green Monster captured Fisk's emotion thanks to a cameraman distracted by a rat—creating footage that forever changed how we see athletes' big moments. Though the Reds won the title the next night, the game remains one of baseball's all-time classics.", "summary_zh": "1975 年 10 月 21 日，波士顿捕手卡尔顿·菲斯克在世界大赛对辛辛那提红人的第六战第十二局下半率先击球。他对帕特·达西一记 1-0 下坠球挥棒，球贴着左外野界外杆飞出，经他拼命挥臂「引导」后判为界内，逼出第七战。稍早替补打击伯尼·卡博第八局三垒打将比分追成 6–6。NBC 藏在「绿色怪物」内的摄像机因摄影师被老鼠分心而拍下菲斯克情绪——这段画面永久改变了人们观看运动员高光的方式。尽管红人次日夺冠，此役仍是棒球史上经典之一。", "body_en": "Carlton Fisk Waves Home Run Fair in Epic 1975 World Series Game 6.\n\nCarlton Fisk leaped into the night air at Fenway Park, waving his arms wildly to coax his deep fly ball fair off the foul pole. That raw, joyous moment in the 12th inning sealed a 7-6 walk-off win for the Red Sox.\n\nOn October 21, 1975, Boston catcher Carlton Fisk led off the bottom of the 12th in Game 6 of the World Series against the Cincinnati Reds. He smashed a 1-0 sinker from Pat Darcy that hugged the left-field foul pole after Fisk's frantic urging, forcing a Game 7.\n\nEarlier, pinch-hitter Bernie Carbo's three-run homer in the eighth had tied it at 6-6. The NBC camera inside the Green Monster captured Fisk's emotion thanks to a cameraman distracted by a rat—creating footage that forever changed how we see athletes' big moments. Though the Reds won the title the next night, the game remains one of baseball's all-time classics.", "body_zh": "卡尔顿·菲斯克挥臂「助攻」本垒打：1975 年世界大赛经典第六战。\n\n卡尔顿·菲斯克在芬威球场跃起，双手狂挥，把深远飞球「招」进界内击中标杆；第十二局这一幕定格红袜 7–6 再见胜。\n\n1975 年 10 月 21 日，波士顿捕手卡尔顿·菲斯克在世界大赛对辛辛那提红人的第六战第十二局下半率先击球。他对帕特·达西一记 1-0 下坠球挥棒，球贴着左外野界外杆飞出，经他拼命挥臂「引导」后判为界内，逼出第七战。\n\n稍早替补打击伯尼·卡博第八局三垒打将比分追成 6–6。NBC 藏在「绿色怪物」内的摄像机因摄影师被老鼠分心而拍下菲斯克情绪——这段画面永久改变了人们观看运动员高光的方式。尽管红人次日夺冠，此役仍是棒球史上经典之一。", "url": "https://x.com/i/trending/2112933588320878832", "category": "Sports", "topics": ["Baseball"], "updated_at": "2026-10-21T15:54:59.000Z"}, {"id": "2112281281501528167", "domain": "体育", "title_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves", "title_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头", "hook_en": "Kyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.", "hook_zh": "凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。", "summary_en": "The Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No. 1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "summary_zh": "这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "body_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves.\n\nKyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.\n\nThe Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No.\n\n1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "body_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头。\n\n凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。\n\n这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。\n\n在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "url": "https://x.com/i/trending/2112281281501528167", "category": "Sports", "topics": [], "updated_at": "2026-10-20T15:54:00.000Z"}, {"id": "2112326602743050735", "domain": "体育", "title_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series", "title_zh": "两支小市场球队进世界大赛，MLB 薪资帽争议再起", "hook_en": "The Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.", "hook_zh": "酿酒人横扫道奇进世界大赛，两支开支靠后的球队会师，引爆“职棒是否该设硬顶”的讨论。", "summary_en": "Brewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion. Owners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "summary_zh": "薪资排名约第 19 的酿酒人四场淘汰高薪道奇，联盟冠军赛收视约 753 万，为 2015 年来最佳，并将对阵光芒争夺两队队史首冠。资方提议 2027 年起设约 2.453 亿美元硬顶与 1.712 亿地板以促平衡，球员工会反对，认为压制工资。小市场球迷欢迎限制囤积球星；批评者称地理位置与文化仍影响自由球员，酿酒人证明精明花钱也能赢。", "body_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series.\n\nThe Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.\n\nBrewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion.\n\nOwners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "body_zh": "两支小市场球队进世界大赛，MLB 薪资帽争议再起。\n\n酿酒人横扫道奇进世界大赛，两支开支靠后的球队会师，引爆“职棒是否该设硬顶”的讨论。\n\n薪资排名约第 19 的酿酒人四场淘汰高薪道奇，联盟冠军赛收视约 753 万，为 2015 年来最佳，并将对阵光芒争夺两队队史首冠。\n\n资方提议 2027 年起设约 2.453 亿美元硬顶与 1.712 亿地板以促平衡，球员工会反对，认为压制工资。小市场球迷欢迎限制囤积球星；批评者称地理位置与文化仍影响自由球员，酿酒人证明精明花钱也能赢。", "url": "https://x.com/i/trending/2112326602743050735", "category": "Sports", "topics": ["MLB"], "updated_at": "2026-10-21T05:20:54.000Z"}, {"id": "2112889351361139036", "domain": "体育", "title_en": "EA FC 27 Teases New FUT Gallery Sets for MLS, NWSL, and Saudi League", "title_zh": "EA Sports FC 27 图鉴将加入 MLS、NWSL 与沙特联主题套装", "hook_en": "Community accounts lit up with Halloween-themed artwork showing glowing league logos and 'NEW SETS COMING' banners, getting players hyped for fresh collectibles.", "hook_zh": "FUT 图鉴即将上线 MLS、NWSL 与沙特联主题套装的截图流出，收藏玩家对自家俱乐部再度兴奋起来。", "summary_en": "Popular FUT accounts shared promotional images and in-game screenshots revealing upcoming Gallery sets for Major League Soccer, the National Women’s Soccer League, and the Roshn Saudi League. These sets let players collect and grade items from the fully licensed leagues—MLS with 30 clubs, NWSL's full women's roster, and Saudi's 18 teams—to earn custom crests, kits, Gallery Tokens, and higher levels. Players are buzzing about pack strategies, market price shifts, and how owned cards will count toward progress, seeing it as a fun way to keep rewards flowing without endless grinding.", "summary_zh": "粉丝发现《EA Sports FC 27》FUT 图鉴即将加入美国职业足球大联盟、国家女子足球联赛与 ROSHN 沙特联等主题套装。玩家可收集对应联赛球员卡以提升图鉴等级并领取外观、代币等奖励——历史中已有道具亦计入进度。交易者正规划如现在完成 MLS 未来之星精选等操作，并讨论旧包是否自动计入、价格会否波动。周期性更新节奏偏缓，便于向 15 级等里程碑稳步推进。", "body_en": "EA Sports FC 27 FUT Gallery Adds MLS, NWSL, and Saudi League Sets.\n\nScreenshots of upcoming MLS, NWSL, and Saudi League sets in the FUT Gallery have collectors eyeing their clubs with fresh excitement.\n\nFans spotted new themed sets coming soon to the FUT Gallery in EA Sports FC 27, covering Major League Soccer, the National Women’s Soccer League, and the ROSHN Saudi League. These additions let players collect player items from the leagues to raise their overall Gallery Level and grab rewards like customizations and tokens—even past items in a player's history count toward the sets.\n\nTraders are planning moves, like completing MLS Future Stars picks now, while wondering if old packs will auto-contribute and how prices might shift. The periodic updates keep the pace relaxed, building toward milestones like Level 15 without rush.", "body_zh": "EA Sports FC 27 图鉴将加入 MLS、NWSL 与沙特联主题套装。\n\nFUT 图鉴即将上线 MLS、NWSL 与沙特联主题套装的截图流出，收藏玩家对自家俱乐部再度兴奋起来。\n\n粉丝发现《EA Sports FC 27》FUT 图鉴即将加入美国职业足球大联盟、国家女子足球联赛与 ROSHN 沙特联等主题套装。玩家可收集对应联赛球员卡以提升图鉴等级并领取外观、代币等奖励——历史中已有道具亦计入进度。\n\n交易者正规划如现在完成 MLS 未来之星精选等操作，并讨论旧包是否自动计入、价格会否波动。周期性更新节奏偏缓，便于向 15 级等里程碑稳步推进。", "url": "https://x.com/i/trending/2112889351361139036", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T16:42:49.000Z"}, {"id": "2112804232634187907", "domain": "体育", "title_en": "NBA Season Tips Off with Thunder Victory and Fan Joy", "title_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾", "hook_en": "Fans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.", "hook_zh": "2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。", "summary_en": "The season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama. Other games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "summary_zh": "赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "body_en": "NBA Season Tips Off with Thunder Victory and Fan Joy.\n\nFans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.\n\nThe season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama.\n\nOther games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "body_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾。\n\n2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。\n\n赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。\n\n另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "url": "https://x.com/i/trending/2112804232634187907", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:17:07.000Z"}, {"id": "2112801176995467757", "domain": "体育", "title_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts", "title_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相", "hook_en": "LeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.", "hook_zh": "勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。", "summary_en": "The Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration. Tyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "summary_zh": "费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "body_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts.\n\nLeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.\n\nThe Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration.\n\nTyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "body_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相。\n\n勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。\n\n费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。\n\n赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "url": "https://x.com/i/trending/2112801176995467757", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:06:29.000Z"}, {"id": "2112718297158332458", "domain": "体育", "title_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener", "title_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛", "hook_en": "On a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.", "hook_zh": "底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。", "summary_en": "The league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers. While some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "summary_zh": "2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "body_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener.\n\nOn a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.\n\nThe league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers.\n\nWhile some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "body_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛。\n\n底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。\n\n2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。\n\n部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "url": "https://x.com/i/trending/2112718297158332458", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T01:36:46.000Z"}, {"id": "2112449095977582635", "domain": "体育", "title_en": "Australia and India Launch Umpire Exchange Program", "title_zh": "澳印启动板球裁判交流项目", "hook_en": "Ben Treloar steps onto Indian pitches for Ranji Trophy matches, while Parashar Joshi heads Down Under for Sheffield Shield games. It's a smart swap giving both umpires hands-on experience in new conditions.", "hook_zh": "本·特雷洛尔将赴印度执法兰吉杯，帕拉沙尔·乔希则赴澳执法谢菲尔德盾——双方在新环境下积累实战经验。", "summary_en": "Cricket Australia and the BCCI announced a reciprocal program where Australian umpire Ben Treloar will officiate two Ranji Trophy matches in India, including Delhi vs. Gujarat from October 18-21 and Mumbai vs. Haryana from October 26-29. In return, Indian umpire Parashar Joshi will handle two Sheffield Shield games and one One-Day Cup match in Australia, starting with Queensland vs. Tasmania at the Gabba on November 11-14. Both bring solid credentials—Treloar with 30 first-class matches and Big Bash experience, Joshi with IPL and domestic stints—and the exchange aims to build ties and sharpen skills through international exposure.", "summary_zh": "澳大利亚板球协会与印度板球控制委员会宣布对等交流：澳籍裁判本·特雷洛尔将在印度执法两场兰吉杯，包括 10 月 18–21 日德里对古吉拉特，以及 10 月 26–29 日孟买对哈里亚纳。印籍裁判帕拉沙尔·乔希则赴澳执法两场谢菲尔德盾及一场一日杯，首场为 11 月 11–14 日加巴球场昆士兰对塔斯马尼亚。特雷洛尔有约 30 场一线比赛与大联盟经验，乔希有印超与国内赛事经历；交流意在加深联系，并通过国际曝光提升执法水平。", "body_en": "Australia and India Launch Umpire Exchange Program.\n\nBen Treloar steps onto Indian pitches for Ranji Trophy matches, while Parashar Joshi heads Down Under for Sheffield Shield games. It's a smart swap giving both umpires hands-on experience in new conditions.\n\nCricket Australia and the BCCI announced a reciprocal program where Australian umpire Ben Treloar will officiate two Ranji Trophy matches in India, including Delhi vs. Gujarat from October 18-21 and Mumbai vs. Haryana from October 26-29.\n\nIn return, Indian umpire Parashar Joshi will handle two Sheffield Shield games and one One-Day Cup match in Australia, starting with Queensland vs. Tasmania at the Gabba on November 11-14. Both bring solid credentials—Treloar with 30 first-class matches and Big Bash experience, Joshi with IPL and domestic stints—and the exchange aims to build ties and sharpen skills through international exposure.", "body_zh": "澳印启动板球裁判交流项目。\n\n本·特雷洛尔将赴印度执法兰吉杯，帕拉沙尔·乔希则赴澳执法谢菲尔德盾——双方在新环境下积累实战经验。\n\n澳大利亚板球协会与印度板球控制委员会宣布对等交流：澳籍裁判本·特雷洛尔将在印度执法两场兰吉杯，包括 10 月 18–21 日德里对古吉拉特，以及 10 月 26–29 日孟买对哈里亚纳。\n\n印籍裁判帕拉沙尔·乔希则赴澳执法两场谢菲尔德盾及一场一日杯，首场为 11 月 11–14 日加巴球场昆士兰对塔斯马尼亚。特雷洛尔有约 30 场一线比赛与大联盟经验，乔希有印超与国内赛事经历；交流意在加深联系，并通过国际曝光提升执法水平。", "url": "https://x.com/i/trending/2112449095977582635", "category": "Sports", "topics": ["Cricket"], "updated_at": "2026-10-20T07:45:38.000Z"}, {"id": "2112930908437426481", "domain": "体育", "title_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment", "title_zh": "勒布朗热麦吐槽尼克斯「冠军哨」", "hook_en": "As the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.", "hook_zh": "尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。", "summary_en": "During the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists. His remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "summary_zh": "尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "body_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment.\n\nAs the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.\n\nDuring the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists.\n\nHis remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "body_zh": "勒布朗热麦吐槽尼克斯「冠军哨」。\n\n尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。\n\n尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。\n\n他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "url": "https://x.com/i/trending/2112930908437426481", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T15:43:54.000Z"}, {"id": "2112826877455053262", "domain": "娱乐", "title_en": "India Adds Three Sites to UNESCO World Heritage Tentative List", "title_zh": "印度新增三处遗址进入联合国教科文组织世界遗产预备名单", "hook_en": "From bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.", "hook_zh": "从安达曼冒泡的泥火山，到马哈纳迪河沿岸古寺，三处印度遗产向全球认可又近一步。", "summary_en": "India's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh. These sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "summary_zh": "印度常驻联合国教科文组织代表团于 2026 年 10 月 20 日宣布，将安达曼-尼科巴群岛的巴拉唐岩溶泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦的希尔普尔文化考古景观列入预备名单。这些地点既有活火山、石灰岩洞穴等独特地质，也有体现印度教、佛教与耆那教遗产及多信仰共处的历史寺庙。联邦部长 Gajendra Singh Shekhawat 称赞希尔普尔在艺术、建筑、灵性与学问上的传统；印度目前已有 45 处列入世界遗产名录。", "body_en": "India Adds Three Sites to UNESCO World Heritage Tentative List.\n\nFrom bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.\n\nIndia's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh.\n\nThese sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "body_zh": "印度新增三处遗址进入联合国教科文组织世界遗产预备名单。\n\n从安达曼冒泡的泥火山，到马哈纳迪河沿岸古寺，三处印度遗产向全球认可又近一步。\n\n印度常驻联合国教科文组织代表团于 2026 年 10 月 20 日宣布，将安达曼-尼科巴群岛的巴拉唐岩溶泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦的希尔普尔文化考古景观列入预备名单。\n\n这些地点既有活火山、石灰岩洞穴等独特地质，也有体现印度教、佛教与耆那教遗产及多信仰共处的历史寺庙。联邦部长 Gajendra Singh Shekhawat 称赞希尔普尔在艺术、建筑、灵性与学问上的传统；印度目前已有 45 处列入世界遗产名录。", "url": "https://x.com/i/trending/2112826877455053262", "category": "News", "topics": ["Travel"], "updated_at": "2026-10-21T11:43:52.000Z"}, {"id": "2112785004996567423", "domain": "娱乐", "title_en": "Pakistani Music Blasts During Sara Ali Khan and Ayushmann Khurrana's Wagah Border Promo", "title_zh": "瓦嘎边境宣传时，巴基斯坦音乐突然放大「整」印度明星", "hook_en": "As Sara Ali Khan and Ayushmann Khurrana spoke into the mic at the Wagah border, Coke Studio tracks like Atif Aslam’s 'Tajdar-e-Haram' suddenly boomed louder from the Pakistani side.", "hook_zh": "萨拉·阿里·汗与阿尤斯曼·库拉纳在瓦嘎边境对着麦克风讲话时，巴基斯坦一侧突然把 Coke Studio 曲目——如阿提夫·阿斯拉姆的《Tajdar-e-Haram》——音量猛然调高。", "summary_en": "The actors visited the Wagah-Attari border to promote their spy comedy *Udta Teer*, where Ayushmann plays a memory-lost Pakistani operative who thinks he's Indian. Pakistani users saw the music volume increase as a playful troll, with clips called 'peak ragebaiting' and 'video of the day.' They also stopped at the Golden Temple on Dussehra, where Sara grew emotional during prayers, adding heartfelt notes to the tour ahead of the film's October 23, 2026 release.", "summary_zh": "两位演员到瓦嘎—阿塔里边境宣传间谍喜剧《Udta Teer》，片中阿尤斯曼饰演失忆后自认印度人的巴基斯坦特工。巴基斯坦网民将音量突增视为戏谑「整活」，片段被称为「顶级激怒诱饵」与「当日视频」。他们还在十胜节前往金庙，萨拉在祷告时情绪激动，为 2026 年 10 月 23 日上映前的宣传之旅添上感性一笔。", "body_en": "Pakistani Music Blasts During Sara Ali Khan and Ayushmann Khurrana's Wagah Border Promo.\n\nAs Sara Ali Khan and Ayushmann Khurrana spoke into the mic at the Wagah border, Coke Studio tracks like Atif Aslam’s 'Tajdar-e-Haram' suddenly boomed louder from the Pakistani side.\n\nThe actors visited the Wagah-Attari border to promote their spy comedy *Udta Teer*, where Ayushmann plays a memory-lost Pakistani operative who thinks he's Indian. Pakistani users saw the music volume increase as a playful troll, with clips called 'peak ragebaiting' and 'video of the day.' They also stopped at the Golden Temple on Dussehra, where Sara grew emotional during prayers, adding heartfelt notes to the tour ahead of the film's October 23, 2026 release.", "body_zh": "瓦嘎边境宣传时，巴基斯坦音乐突然放大「整」印度明星。\n\n萨拉·阿里·汗与阿尤斯曼·库拉纳在瓦嘎边境对着麦克风讲话时，巴基斯坦一侧突然把 Coke Studio 曲目——如阿提夫·阿斯拉姆的《Tajdar-e-Haram》——音量猛然调高。\n\n两位演员到瓦嘎—阿塔里边境宣传间谍喜剧《Udta Teer》，片中阿尤斯曼饰演失忆后自认印度人的巴基斯坦特工。\n\n巴基斯坦网民将音量突增视为戏谑「整活」，片段被称为「顶级激怒诱饵」与「当日视频」。他们还在十胜节前往金庙，萨拉在祷告时情绪激动，为 2026 年 10 月 23 日上映前的宣传之旅添上感性一笔。", "url": "https://x.com/i/trending/2112785004996567423", "category": "News", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T16:42:49.000Z"}, {"id": "2112918023249989711", "domain": "娱乐", "title_en": "Sunshine Benzi Shares Notebook-to-Studio Process for 'Forbes List'", "title_zh": "Sunshine Benzi 分享《Forbes List》从笔记本到录音棚的创作过程", "hook_en": "Sunshine Benzi flips through her notebook in the studio, pen flying as she crafts lyrics for her new track. Fans can't get enough of her hands-on hustle.", "hook_zh": "Sunshine Benzi 在录音棚翻着笔记本奋笔写词，粉丝为她亲力亲为的创作节奏着迷。", "summary_en": "The 24-year-old Chicago-area rapper, born Sunshine Kathleen Holt in Pontiac, Illinois, posted behind-the-scenes clips of writing and recording 'Forbes List,' produced by Bangladesh of Nicki Minaj fame and Chinoo.xo. Viewers praise her raw talent, work ethic, and poetry-rooted approach, with comments like 'this chick can rap' and 'RAW talent' flooding in. She first gained notice in late 2025 with her TikTok freestyle 'Trump the Bill,' followed by singles like 'Barracuda' and a December 2026 Miss Bellum Tour. While some note her background as a white artist in hip-hop, the buzz focuses on her focused craft and building momentum.", "summary_zh": "这位 24 岁、生于伊利诺伊州庞蒂亚克的芝加哥地区说唱歌手 Sunshine Kathleen Holt，晒出创作与录制《Forbes List》的幕后片段，制作人包括曾与 Nicki Minaj 合作的 Bangladesh 以及 Chinoo.xo。观众称赞其原始才华、工作态度与诗歌根底，评论区常见「这姑娘会说唱」「真正的天赋」等话。她 2025 年末因 TikTok 自由说唱《Trump the Bill》走红，随后发行《Barracuda》等单曲，并计划 2026 年 12 月 Miss Bellum 巡演。虽有人提到她作为白人艺人进入嘻哈圈的背景，讨论焦点仍在其专注打磨与持续升温的势头。", "body_en": "Sunshine Benzi Shares Notebook-to-Studio Process for 'Forbes List'.\n\nSunshine Benzi flips through her notebook in the studio, pen flying as she crafts lyrics for her new track. Fans can't get enough of her hands-on hustle.\n\nThe 24-year-old Chicago-area rapper, born Sunshine Kathleen Holt in Pontiac, Illinois, posted behind-the-scenes clips of writing and recording 'Forbes List,' produced by Bangladesh of Nicki Minaj fame and Chinoo.xo. Viewers praise her raw talent, work ethic, and poetry-rooted approach, with comments like 'this chick can rap' and 'RAW talent' flooding in.\n\nShe first gained notice in late 2025 with her TikTok freestyle 'Trump the Bill,' followed by singles like 'Barracuda' and a December 2026 Miss Bellum Tour. While some note her background as a white artist in hip-hop, the buzz focuses on her focused craft and building momentum.", "body_zh": "Sunshine Benzi 分享《Forbes List》从笔记本到录音棚的创作过程。\n\nSunshine Benzi 在录音棚翻着笔记本奋笔写词，粉丝为她亲力亲为的创作节奏着迷。\n\n这位 24 岁、生于伊利诺伊州庞蒂亚克的芝加哥地区说唱歌手 Sunshine Kathleen Holt，晒出创作与录制《Forbes List》的幕后片段，制作人包括曾与 Nicki Minaj 合作的 Bangladesh 以及 Chinoo.xo。观众称赞其原始才华、工作态度与诗歌根底，评论区常见「这姑娘会说唱」「真正的天赋」等话。\n\n她 2025 年末因 TikTok 自由说唱《Trump the Bill》走红，随后发行《Barracuda》等单曲，并计划 2026 年 12 月 Miss Bellum 巡演。虽有人提到她作为白人艺人进入嘻哈圈的背景，讨论焦点仍在其专注打磨与持续升温的势头。", "url": "https://x.com/i/trending/2112918023249989711", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T14:50:09.000Z"}, {"id": "2112887415811485869", "domain": "娱乐", "title_en": "Cardi B Graces New York Times T Magazine’s Greats Issue", "title_zh": "Cardi B 登上《纽约时报》T 杂志「伟大」特刊", "hook_en": "Cardi B owns the streets of New York City in sleek black gowns, her platinum curls and bold confidence lighting up every frame of the photoshoot.", "hook_zh": "Cardi B 以利落黑礼服「占领」纽约街头，铂金卷发与自信气场点亮每一帧写真。", "summary_en": "As the face of T Magazine’s 2026 “The Greats” issue, Cardi B stars in powerful portraits by Ilya Lipkin, wearing Chanel and other high-fashion pieces amid urban backdrops like flowing street trains and industrial stairs. In the accompanying interview “The Many Lives of Cardi B,” she shares her influences—naming Beyoncé her top live performer—while calling herself her greatest creation (thanks to her parents and surgeon) and her four children her proudest achievement. Fans love the elegant, empowered shots that capture her Bronx roots and global icon status, with the full profile out in the October 21 edition.", "summary_zh": "作为 T 杂志 2026「The Greats」特刊封面人物，Cardi B 在摄影师 Ilya Lipkin 镜头下身着香奈儿等高定时装，置身流动街头列车与工业阶梯等都市背景。随刊访谈《Cardi B 的多重人生》中，她谈及影响来源——称碧昂丝是她心中最佳现场表演者——并说自己是「最伟大的创作」（感谢父母与整外医生），四个孩子则是最骄傲成就。粉丝喜爱这些优雅而有力量、兼顾布朗克斯根脉与全球偶像气质的照片；完整专访刊于 10 月 21 日版。", "body_en": "Cardi B Graces New York Times T Magazine’s Greats Issue.\n\nCardi B owns the streets of New York City in sleek black gowns, her platinum curls and bold confidence lighting up every frame of the photoshoot.\n\nAs the face of T Magazine’s 2026 “The Greats” issue, Cardi B stars in powerful portraits by Ilya Lipkin, wearing Chanel and other high-fashion pieces amid urban backdrops like flowing street trains and industrial stairs.\n\nIn the accompanying interview “The Many Lives of Cardi B,” she shares her influences—naming Beyoncé her top live performer—while calling herself her greatest creation (thanks to her parents and surgeon) and her four children her proudest achievement. Fans love the elegant, empowered shots that capture her Bronx roots and global icon status, with the full profile out in the October 21 edition.", "body_zh": "Cardi B 登上《纽约时报》T 杂志「伟大」特刊。\n\nCardi B 以利落黑礼服「占领」纽约街头，铂金卷发与自信气场点亮每一帧写真。\n\n作为 T 杂志 2026「The Greats」特刊封面人物，Cardi B 在摄影师 Ilya Lipkin 镜头下身着香奈儿等高定时装，置身流动街头列车与工业阶梯等都市背景。\n\n随刊访谈《Cardi B 的多重人生》中，她谈及影响来源——称碧昂丝是她心中最佳现场表演者——并说自己是「最伟大的创作」（感谢父母与整外医生），四个孩子则是最骄傲成就。粉丝喜爱这些优雅而有力量、兼顾布朗克斯根脉与全球偶像气质的照片；完整专访刊于 10 月 21 日版。", "url": "https://x.com/i/trending/2112887415811485869", "category": "Entertainment", "topics": ["Music", "Celebrity"], "updated_at": "2026-10-21T15:03:56.000Z"}, {"id": "2112920266284417440", "domain": "娱乐", "title_en": "VisionQuest Episodes Thrill Fans with Ultron Twist and Stunning VFX", "title_zh": "《VisionQuest》新集奥创反转与特效引爆讨论", "hook_en": "Paul Bettany's Vision faces a shocking Ultron takeover in the latest episodes, leaving fans emotional and praising the top-tier CGI that brings it all to life.", "hook_zh": "保罗·贝坦尼饰演的幻视遭遇奥创夺控的震撼桥段，粉丝情绪激动，并盛赞顶级 CGI。", "summary_en": "Episodes 3 and 4 of VisionQuest, titled 'Reboot' and 'Malware,' dropped on Disney+ this week, featuring Vision on the run with a boy named Tommy who might be his son, while battling AI personas like James Spader's Ultron in his mind. The installments deliver intense callbacks to Avengers: Age of Ultron, an exorcism scene, and Ultron seizing control of Vision's body, which fans call insanely good and emotionally gripping. Reviewers highlight deeper bonds between characters, Bettany's mix of comedy and drama, and strong early buzz positioning it as a potential top MCU show, with weekly episodes continuing.", "summary_zh": "《VisionQuest》第 3、4 集「Reboot」「Malware」本周登陆 Disney+：幻视与可能是其子的男孩汤米一路逃亡，同时在意识中对抗詹姆斯·斯派德配音的奥创等 AI 人格。两集密集回扣《复仇者联盟：奥创纪元》，含驱魔场面与奥创夺取幻视身体，粉丝称「疯狂好看」且情感冲击强。评论强调角色羁绊加深、贝坦尼喜悲切换，以及将其推为潜在顶级漫威剧的早期热度；后续仍将每周更新。", "body_en": "VisionQuest Episodes Thrill Fans with Ultron Twist and Stunning VFX.\n\nPaul Bettany's Vision faces a shocking Ultron takeover in the latest episodes, leaving fans emotional and praising the top-tier CGI that brings it all to life.\n\nEpisodes 3 and 4 of VisionQuest, titled 'Reboot' and 'Malware,' dropped on Disney+ this week, featuring Vision on the run with a boy named Tommy who might be his son, while battling AI personas like James Spader's Ultron in his mind.\n\nThe installments deliver intense callbacks to Avengers: Age of Ultron, an exorcism scene, and Ultron seizing control of Vision's body, which fans call insanely good and emotionally gripping. Reviewers highlight deeper bonds between characters, Bettany's mix of comedy and drama, and strong early buzz positioning it as a potential top MCU show, with weekly episodes continuing.", "body_zh": "《VisionQuest》新集奥创反转与特效引爆讨论。\n\n保罗·贝坦尼饰演的幻视遭遇奥创夺控的震撼桥段，粉丝情绪激动，并盛赞顶级 CGI。\n\n《VisionQuest》第 3、4 集「Reboot」「Malware」本周登陆 Disney+：幻视与可能是其子的男孩汤米一路逃亡，同时在意识中对抗詹姆斯·斯派德配音的奥创等 AI 人格。\n\n两集密集回扣《复仇者联盟：奥创纪元》，含驱魔场面与奥创夺取幻视身体，粉丝称「疯狂好看」且情感冲击强。评论强调角色羁绊加深、贝坦尼喜悲切换，以及将其推为潜在顶级漫威剧的早期热度；后续仍将每周更新。", "url": "https://x.com/i/trending/2112920266284417440", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T15:02:11.000Z"}, {"id": "2112078869360726394", "domain": "娱乐", "title_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore", "title_zh": "Kwong Lingling 亮相新加坡卡地亚「Into The Wild」活动", "hook_en": "Lingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.", "hook_zh": "Kwong Lingling 身着闪亮黑色亮片礼服、搭配戏剧感花卉手套，在丛林灵感布景前自信亮相，成为卡地亚雅集焦点。", "summary_en": "On October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry. She stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "summary_zh": "10 月 19 日，泰国女演员 Kwong Lingling 以精致造型出席新加坡卡地亚「Into The Wild」活动，庆祝品牌标志性豹纹与动物灵感珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配粗银链、闪亮手镯与夸张耳环。粉丝盛赞其笑容与气场，有人写道「优雅有了名字」。沉浸式体验 10 月 21 日至 25 日在 17 Rochester Park 对公众开放，部分元素将在 ION Orchard 延续至 11 月初。", "body_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore.\n\nLingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.\n\nOn October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry.\n\nShe stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "body_zh": "Kwong Lingling 亮相新加坡卡地亚「Into The Wild」活动。\n\nKwong Lingling 身着闪亮黑色亮片礼服、搭配戏剧感花卉手套，在丛林灵感布景前自信亮相，成为卡地亚雅集焦点。\n\n10 月 19 日，泰国女演员 Kwong Lingling 以精致造型出席新加坡卡地亚「Into The Wild」活动，庆祝品牌标志性豹纹与动物灵感珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配粗银链、闪亮手镯与夸张耳环。\n\n粉丝盛赞其笑容与气场，有人写道「优雅有了名字」。沉浸式体验 10 月 21 日至 25 日在 17 Rochester Park 对公众开放，部分元素将在 ION Orchard 延续至 11 月初。", "url": "https://x.com/i/trending/2112078869360726394", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T06:02:16.000Z"}, {"id": "2112653365356433717", "domain": "娱乐", "title_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk", "title_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论", "hook_en": "A post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.", "hook_zh": "有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。", "summary_en": "Ariana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office. Seyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "summary_zh": "爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "body_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk.\n\nA post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.\n\nAriana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office.\n\nSeyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "body_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论。\n\n有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。\n\n爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。\n\n粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "url": "https://x.com/i/trending/2112653365356433717", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T00:31:26.000Z"}, {"id": "2112605676610478278", "domain": "娱乐", "title_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'", "title_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖", "hook_en": "Jaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.", "hook_zh": "「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。", "summary_en": "The Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April. The ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "summary_zh": "评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "body_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'.\n\nJaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.\n\nThe Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April.\n\nThe ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "body_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖。\n\n「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。\n\n评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。\n\n典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "url": "https://x.com/i/trending/2112605676610478278", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T18:15:13.000Z"}, {"id": "2112801173090587112", "domain": "娱乐", "title_en": "Thai Star Lingling Kwong Shines at Cartier's Wild Jewelry Event in Singapore", "title_zh": "Lingling Kwong 亮相新加坡卡地亚活动", "hook_en": "Lingling Sirilak Kwong stepped into a lush jungle paradise, her sparkling gowns and bold jewels perfectly capturing the night's animal-inspired magic.", "hook_zh": "Lingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。", "summary_en": "Thai actress Lingling Sirilak Kwong flew from Thailand to attend Cartier’s “Into the Wild” celebration at Rochester Park, where historic bungalows became immersive gardens filled with dance, music, and fauna-flora tributes. She turned heads in multiple glamorous looks, like a black sequined gown with diamond, onyx, and colorful stone pieces evoking tigers and parrots, plus a grey textured dress amid rattan and plants. Fans and media praised her elegant style matching the event's luxurious wild vibe, with the Faune & Flore exhibition open through October 25.", "summary_zh": "10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "body_en": "Lingling Kwong Shines at Cartier Event in Singapore.\n\nLingling Kwong stepped into Cartier’s wild jungle-themed world in a sleek black sequined gown and dramatic gloves, turning heads with her timeless elegance.\n\nAt the 'Into the Wild' immersive experience in Rochester Park on October 21, Kwong wore pieces from Cartier’s new Faune & Flore collection, featuring onyx, sapphires, and diamonds that fans called striking and queenly.\n\nThe event celebrates the brand’s animal-inspired designs through October 25. That same day, she promoted Her Hyness sunscreen at a big fan event in Bangkok, highlighting her rising star in luxury and beauty.", "body_zh": "Lingling Kwong 亮相新加坡卡地亚活动。\n\nLingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。\n\n10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。\n\n活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "url": "https://x.com/i/trending/2112801173090587112", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T14:14:44.000Z"}, {"id": "2112244938171924792", "domain": "娱乐", "title_en": "Taylor Swift Debuts 'The Fate of Ophelia' at Academy Museum Gala", "title_zh": "泰勒·斯威夫特时隔近两年带全乐队亮相学院博物馆晚会", "hook_en": "Taylor Swift stepped onstage in a shimmering navy gown, sharing her new song 'The Fate of Ophelia' live for the first time with her band after nearly two years.", "hook_zh": "泰勒带全乐队近两年来首次登台，把一场名流晚宴变成音乐高光。", "summary_en": "At the October 17 Academy Museum Gala in Los Angeles, Swift opened with 'Blank Space,' debuted the track, and closed with 'Love Story' and her Toy Story 5 song 'I Knew It, I Knew You.' She paid for her own ticket, performed for free, and later called reuniting with her band a 'VIBE' on Instagram. The event raised over $14 million for the museum, honoring stars like Charlize Theron and Colman Domingo amid horror exhibition décor. An insider noted how she charmed the room, making everyone feel special.", "summary_zh": "在致敬约翰·卡朋特、科尔曼·多明戈与查理兹·塞隆的 2026 学院博物馆晚会上，她演唱《Blank Space》、2025 专辑中《The Fate of Ophelia》的现场首唱、为《玩具总动员 5》创作的《I Knew It, I Knew You》以及《Love Story》。柯南·奥布莱恩介绍时称她“约翰、保罗、乔治与林戈集于一身”。晚会呼应博物馆恐怖展主题，筹得逾 1400 万美元；她自费购票并义务演出，事后在 Instagram 称当晚很有感觉。", "body_en": "Taylor Swift Delivers Surprise Band Performance at Academy Museum Gala.\n\nTaylor Swift stepped back into the spotlight with her full band for the first time in nearly two years, turning a glamorous gala into a musical highlight.\n\nAt the 2026 Academy Museum Gala honoring John Carpenter, Colman Domingo, and Charlize Theron, Swift performed four songs: 'Blank Space,' the live debut of 'The Fate of Ophelia' from her 2025 album The Life of a Showgirl, 'I Knew It, I Knew You' from Toy Story 5, and 'Love Story.' Introduced by Conan O’Brien, who called her 'John, Paul, George and Ringo all in one,' she dazzled in gown changes from Dior to Ralph Lauren and mingled with Toy Story 5 castmates. The event, themed around the museum’s 'The Horror Show' exhibition, raised over $14 million, with Swift paying her own ticket and performing for free, later calling it a 'VIBE' on Instagram.", "body_zh": "泰勒·斯威夫特时隔近两年带全乐队亮相学院博物馆晚会。\n\n泰勒带全乐队近两年来首次登台，把一场名流晚宴变成音乐高光。\n\n在致敬约翰·卡朋特、科尔曼·多明戈与查理兹·塞隆的 2026 学院博物馆晚会上，她演唱《Blank Space》、2025 专辑中《The Fate of Ophelia》的现场首唱、为《玩具总动员 5》创作的《I Knew It, I Knew You》以及《Love Story》。\n\n柯南·奥布莱恩介绍时称她“约翰、保罗、乔治与林戈集于一身”。晚会呼应博物馆恐怖展主题，筹得逾 1400 万美元；她自费购票并义务演出，事后在 Instagram 称当晚很有感觉。", "url": "https://x.com/i/trending/2112244938171924792", "category": "Entertainment", "topics": ["Music", "Celebrity"], "updated_at": "2026-10-21T16:34:38.000Z"}, {"id": "2112326598276039153", "domain": "娱乐", "title_en": "Disney's 'Hexed' Unveils Posters, Tickets, and Hailee Steinfeld Song", "title_zh": "迪士尼动画《Hexed》释出海报、开售门票并公布海莉·斯坦菲尔德主题曲", "hook_en": "Billie Doe, an impulsive teen with newfound magical powers, leaps from suburbia into a vibrant witch realm alongside her mom. Disney Animation just made it easier to join her adventure with fresh posters and tickets on sale.", "hook_zh": "冲动少女 Billie Doe 刚觉醒魔法，与母亲一道从郊区跃入绚丽女巫世界。迪士尼动画以新海报与开售门票，邀请观众一起踏上冒险。", "summary_en": "The animated fantasy 'Hexed' follows Billie, voiced by Hailee Steinfeld, as she teams with her cautious mother Alice (Rashida Jones) to uncover family secrets in the witch world of Hexe. Jodie Foster voices the sinister Queen Celeste, and Walton Goggins brings a three-eyed magical cat to life. New colorful posters spotlight Billie's spell-casting in glowing forests, while Steinfeld covers The Cars' 'Magic' for the soundtrack dropping October 23, and composer Kris Bowers blends orchestral and experimental sounds. Tickets are live now for the November 25, 2026 theatrical release, including RealD 3D and 4DX formats.", "summary_zh": "动画奇幻片《Hexed》讲述由海莉·斯坦菲尔德配音的 Billie，与谨慎母亲 Alice（拉希达·琼斯配音）在女巫国度 Hexe 揭开家族秘密。朱迪·福斯特为阴险女王 Celeste 献声，沃尔顿·戈金斯则为三眼魔法猫配音。新彩色海报突出 Billie 在发光森林施法；斯坦菲尔德翻唱 The Cars 的《Magic》将于 10 月 23 日随原声带发行，作曲家克里斯·鲍尔斯融合管弦与实验音色。2026 年 11 月 25 日院线上映门票现已开售，含 RealD 3D 与 4DX 场次。", "body_en": "Disney's 'Hexed' Unveils Posters, Tickets, and Hailee Steinfeld Song.\n\nBillie Doe, an impulsive teen with newfound magical powers, leaps from suburbia into a vibrant witch realm alongside her mom. Disney Animation just made it easier to join her adventure with fresh posters and tickets on sale.\n\nThe animated fantasy 'Hexed' follows Billie, voiced by Hailee Steinfeld, as she teams with her cautious mother Alice (Rashida Jones) to uncover family secrets in the witch world of Hexe. Jodie Foster voices the sinister Queen Celeste, and Walton Goggins brings a three-eyed magical cat to life.\n\nNew colorful posters spotlight Billie's spell-casting in glowing forests, while Steinfeld covers The Cars' 'Magic' for the soundtrack dropping October 23, and composer Kris Bowers blends orchestral and experimental sounds. Tickets are live now for the November 25, 2026 theatrical release, including RealD 3D and 4DX formats.", "body_zh": "迪士尼动画《Hexed》释出海报、开售门票并公布海莉·斯坦菲尔德主题曲。\n\n冲动少女 Billie Doe 刚觉醒魔法，与母亲一道从郊区跃入绚丽女巫世界。迪士尼动画以新海报与开售门票，邀请观众一起踏上冒险。\n\n动画奇幻片《Hexed》讲述由海莉·斯坦菲尔德配音的 Billie，与谨慎母亲 Alice（拉希达·琼斯配音）在女巫国度 Hexe 揭开家族秘密。朱迪·福斯特为阴险女王 Celeste 献声，沃尔顿·戈金斯则为三眼魔法猫配音。\n\n新彩色海报突出 Billie 在发光森林施法；斯坦菲尔德翻唱 The Cars 的《Magic》将于 10 月 23 日随原声带发行，作曲家克里斯·鲍尔斯融合管弦与实验音色。2026 年 11 月 25 日院线上映门票现已开售，含 RealD 3D 与 4DX 场次。", "url": "https://x.com/i/trending/2112326598276039153", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T00:38:48.000Z"}, {"id": "2112433199888679267", "domain": "科学", "title_en": "AI Predicts Cancer Survival from Face Photos", "title_zh": "AI 凭面部照片预测癌症生存风险", "hook_en": "Doctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.", "hook_zh": "医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。", "summary_en": "Researchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "summary_zh": "麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "body_en": "AI Predicts Cancer Survival from Face Photos.\n\nDoctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.\n\nResearchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation.\n\nWhile promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "body_zh": "AI 凭面部照片预测癌症生存风险。\n\n医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。\n\n麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。\n\n工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "url": "https://x.com/i/trending/2112433199888679267", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T21:07:35.000Z"}, {"id": "2112771430316404992", "domain": "科学", "title_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living", "title_zh": "生物圈 2 号实验再引「自给生存」讨论", "hook_en": "Eight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.", "hook_zh": "1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。", "summary_en": "The $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "summary_zh": "耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "body_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living.\n\nEight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.\n\nThe $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages.\n\nA popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "body_zh": "生物圈 2 号实验再引「自给生存」讨论。\n\n1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。\n\n耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。\n\n热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "url": "https://x.com/i/trending/2112771430316404992", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112514540671730138", "domain": "科学", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade.\n\nPeople share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z"}, {"id": "2112833225118625949", "domain": "科学", "title_en": "Nigeria Debunks Viral Claims on US Medical Aid Deal", "title_zh": "尼日利亚澄清美医疗援助协议谣言", "hook_en": "Panic spread online after posts claimed a US deal would block Nigeria's drug agency from testing free vaccines and medicines. Officials stepped in swiftly to set the record straight.", "hook_zh": "网传美方协议将阻止尼日利亚药监局检测免费疫苗与药品，引发恐慌；官方迅速出面澄清。", "summary_en": "Viral messages alleged a $3 billion US aid package for malaria and other diseases barred NAFDAC from reviewing supplies, sparking fears of unsafe products and lost sovereignty—claims that Ghana supposedly rejected. NAFDAC's Director-General Prof. Mojisola Adeyeye clarified on October 20, 2026, that the agency keeps full authority: US FDA-approved products get expedited review due to existing reliance, but all undergo safety checks, especially non-US ones, with tracking via blockchain. The five-year MoU, signed December 2025, provides nearly $2 billion in declining US grants for HIV/AIDS and health programs, while Nigeria boosts its spending to $3 billion for self-reliance.", "summary_zh": "病毒式信息称约 30 亿美元疟疾等疾病美援方案禁止 NAFDAC 审查供应，引发不安全产品与主权旁落担忧——并称加纳已拒绝类似条款。NAFDAC 总干事莫吉索拉·阿德耶耶教授 2026 年 10 月 20 日澄清：机构仍保有完全权力；美 FDA 已批产品因既有互认可加快审评，但全部须过安全关，尤其非美产品，并以区块链追踪。该五年谅解备忘录于 2025 年 12 月签署，提供近 20 亿美元逐年递减的美方 HIV/AIDS 与卫生拨款，同时尼日利亚将自有投入提至约 30 亿美元以增强自立。", "body_en": "Nigeria Debunks Viral Claims on US Medical Aid Deal.\n\nPanic spread online after posts claimed a US deal would block Nigeria's drug agency from testing free vaccines and medicines. Officials stepped in swiftly to set the record straight.\n\nViral messages alleged a $3 billion US aid package for malaria and other diseases barred NAFDAC from reviewing supplies, sparking fears of unsafe products and lost sovereignty—claims that Ghana supposedly rejected. NAFDAC's Director-General Prof.\n\nMojisola Adeyeye clarified on October 20, 2026, that the agency keeps full authority: US FDA-approved products get expedited review due to existing reliance, but all undergo safety checks, especially non-US ones, with tracking via blockchain. The five-year MoU, signed December 2025, provides nearly $2 billion in declining US grants for HIV/AIDS and health programs, while Nigeria boosts its spending to $3 billion for self-reliance.", "body_zh": "尼日利亚澄清美医疗援助协议谣言。\n\n网传美方协议将阻止尼日利亚药监局检测免费疫苗与药品，引发恐慌；官方迅速出面澄清。\n\n病毒式信息称约 30 亿美元疟疾等疾病美援方案禁止 NAFDAC 审查供应，引发不安全产品与主权旁落担忧——并称加纳已拒绝类似条款。\n\nNAFDAC 总干事莫吉索拉·阿德耶耶教授 2026 年 10 月 20 日澄清：机构仍保有完全权力；美 FDA 已批产品因既有互认可加快审评，但全部须过安全关，尤其非美产品，并以区块链追踪。该五年谅解备忘录于 2025 年 12 月签署，提供近 20 亿美元逐年递减的美方 HIV/AIDS 与卫生拨款，同时尼日利亚将自有投入提至约 30 亿美元以增强自立。", "url": "https://x.com/i/trending/2112833225118625949", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T11:29:22.000Z"}, {"id": "2112620323275485557", "domain": "科学", "title_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides", "title_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学", "hook_en": "Cancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.", "hook_zh": "同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。", "summary_en": "Holon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests. In tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "summary_zh": "Holon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "body_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides.\n\nCancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.\n\nHolon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests.\n\nIn tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "body_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学。\n\n同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。\n\nHolon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。\n\n联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "url": "https://x.com/i/trending/2112620323275485557", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T01:29:19.000Z"}, {"id": "2112552619117891920", "domain": "科学", "title_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo", "title_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制", "hook_en": "A detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.", "hook_zh": "详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。", "summary_en": "Researchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more. The 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "summary_zh": "McCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "body_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo.\n\nA detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.\n\nResearchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more.\n\nThe 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "body_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制。\n\n详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。\n\nMcCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。\n\n作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "url": "https://x.com/i/trending/2112552619117891920", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T20:43:03.000Z"}, {"id": "2112623559876952326", "domain": "科学", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "Reflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\nReflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。\n\n综合以上信息，Reflect Orbital 在加州沙漠模拟「轨道阳光」一事持续引发关注。", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z"}, {"id": "2112820742060495085", "domain": "科学", "title_en": "Rizhao Residents Watch Rocket Launch from Home Windows", "title_zh": "日照市民在家门口「看火箭」升空", "hook_en": "People in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.", "hook_zh": "中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。", "summary_en": "On October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit. The satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "summary_zh": "2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "body_en": "Rizhao Residents Watch Rocket Launch from Home Windows.\n\nPeople in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.\n\nOn October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit.\n\nThe satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "body_zh": "日照市民在家门口「看火箭」升空。\n\n中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。\n\n2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。\n\n卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "url": "https://x.com/i/trending/2112820742060495085", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T08:24:00.000Z"}, {"id": "2112891430113075386", "domain": "科学", "title_en": "CHOP's Anesthesia Flu Shots Draw Doctor and Parent Backlash", "title_zh": "费城儿童医院麻醉中接种流感疫苗引医生与家长反弹", "hook_en": "A Philadelphia children's hospital started giving flu shots to kids already under anesthesia for procedures, helping thousands avoid needles—but doctors are calling it a dangerous gamble.", "hook_zh": "费城一家儿童医院开始在患儿已接受麻醉做手术时顺带打流感针，帮数千人避开针头恐惧——但有医生称这是危险赌博。", "summary_en": "Children's Hospital of Philadelphia launched its 'Close Your Eyes, We'll Immunize' program in 2023, delivering over 2,000 flu vaccine doses during the 2025-2026 season to sedated pediatric patients. About one-third of families said their child would have skipped the shot due to needle fears or other barriers, aligning with CDC and AAP guidance to vaccinate whenever possible. Critics like anesthesiologist Madhava Setty call it 'stunningly irresponsible' over risks like fevers mimicking anesthesia reactions or rare allergies during surgery, while CHOP reports no serious complications and notes families can opt out. Similar programs at places like Children's Hospital Colorado have vaccinated over 18,000 kids since 2020.", "summary_zh": "费城儿童医院自 2023 年推出「闭上眼睛，我们来接种」计划，2025–2026 季已向镇静患儿接种逾 2000 剂流感疫苗。约三分之一家庭表示孩子本会因怕针或其他障碍跳过接种，此举亦契合疾控中心与美国儿科学会「能打就打」的指导。麻醉科医生 Madhava Setty 等批评者称「惊人地不负责任」，担忧发烧混淆麻醉反应或术中罕见过敏；院方称未见严重并发症，并允许家庭选择退出。科罗拉多儿童医院等类似项目自 2020 年以来已为逾 1.8 万名儿童接种。", "body_en": "CHOP's Anesthesia Flu Shots Draw Doctor and Parent Backlash.\n\nA Philadelphia children's hospital started giving flu shots to kids already under anesthesia for procedures, helping thousands avoid needles—but doctors are calling it a dangerous gamble.\n\nChildren's Hospital of Philadelphia launched its 'Close Your Eyes, We'll Immunize' program in 2023, delivering over 2,000 flu vaccine doses during the 2025-2026 season to sedated pediatric patients. About one-third of families said their child would have skipped the shot due to needle fears or other barriers, aligning with CDC and AAP guidance to vaccinate whenever possible.\n\nCritics like anesthesiologist Madhava Setty call it 'stunningly irresponsible' over risks like fevers mimicking anesthesia reactions or rare allergies during surgery, while CHOP reports no serious complications and notes families can opt out. Similar programs at places like Children's Hospital Colorado have vaccinated over 18,000 kids since 2020.", "body_zh": "费城儿童医院麻醉中接种流感疫苗引医生与家长反弹。\n\n费城一家儿童医院开始在患儿已接受麻醉做手术时顺带打流感针，帮数千人避开针头恐惧——但有医生称这是危险赌博。\n\n费城儿童医院自 2023 年推出「闭上眼睛，我们来接种」计划，2025–2026 季已向镇静患儿接种逾 2000 剂流感疫苗。约三分之一家庭表示孩子本会因怕针或其他障碍跳过接种，此举亦契合疾控中心与美国儿科学会「能打就打」的指导。\n\n麻醉科医生 Madhava Setty 等批评者称「惊人地不负责任」，担忧发烧混淆麻醉反应或术中罕见过敏；院方称未见严重并发症，并允许家庭选择退出。科罗拉多儿童医院等类似项目自 2020 年以来已为逾 1.8 万名儿童接种。", "url": "https://x.com/i/trending/2112891430113075386", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-21T15:22:23.000Z"}, {"id": "2111892089000915435", "domain": "科学", "title_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds", "title_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道", "hook_en": "Thousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.", "hook_zh": "10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。", "summary_en": "Ruto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units. He inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "summary_zh": "鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "body_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds.\n\nThousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.\n\nRuto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units.\n\nHe inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "body_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道。\n\n10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。\n\n鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。\n\n行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "url": "https://x.com/i/trending/2111892089000915435", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T06:36:12.000Z"}, {"id": "2112244933029761280", "domain": "科学", "title_en": "Dr. Priti Adani Outlines National Expansion of Healthcare Education and Research", "title_zh": "普里蒂·阿达尼勾勒医疗教育与科研全国扩张", "hook_en": "At the Adani Institute's 17th convocation in Wardha, Dr. Priti Adani spoke directly to graduates about blending compassion with cutting-edge care.", "hook_zh": "在瓦尔达第 17 届毕业典礼上，她勉励毕业生把关怀与尖端医疗结合。", "summary_en": "Dr. Priti Adani, Chancellor of the Adani Institute of Higher Education and Research, announced plans to strengthen Wardha and Nagpur campuses with modern medical equipment, advanced research, and super-specialty services over the next two years. The institute aims to build additional campuses across India, tailored to regional needs while upholding consistent standards and the principle of 'Seva hi sadhana hai'—service as devotion. Guided by UN Sustainable Development Goals, efforts will focus on preventive care, disease prevention, affordable treatments, and support for disadvantaged students, with Dr. Adani urging graduates to prioritize patients' dignity and lifelong learning alongside technical skills.", "summary_zh": "阿达尼高等教育与研究院院长普里蒂·阿达尼宣布，未来两年将加强瓦尔达与那格浦尔校区的现代医疗设备、前沿科研与超专科服务，并按地区需求在全国增设校区，坚持“服务即修行”。计划对标联合国可持续发展目标，聚焦预防、可负担治疗与弱势学生支持，她呼吁毕业生在技术之外守护患者尊严与终身学习。", "body_en": "Dr. Priti Adani Outlines National Expansion of Healthcare Education and Research.\n\nAt the Adani Institute's 17th convocation in Wardha, Dr. Priti Adani spoke directly to graduates about blending compassion with cutting-edge care.\n\nDr. Priti Adani, Chancellor of the Adani Institute of Higher Education and Research, announced plans to strengthen Wardha and Nagpur campuses with modern medical equipment, advanced research, and super-specialty services over the next two years.\n\nThe institute aims to build additional campuses across India, tailored to regional needs while upholding consistent standards and the principle of 'Seva hi sadhana hai'—service as devotion. Guided by UN Sustainable Development Goals, efforts will focus on preventive care, disease prevention, affordable treatments, and support for disadvantaged students, with Dr. Adani urging graduates to prioritize patients' dignity and lifelong learning alongside technical skills.", "body_zh": "普里蒂·阿达尼勾勒医疗教育与科研全国扩张。\n\n在瓦尔达第 17 届毕业典礼上，她勉励毕业生把关怀与尖端医疗结合。\n\n阿达尼高等教育与研究院院长普里蒂·阿达尼宣布，未来两年将加强瓦尔达与那格浦尔校区的现代医疗设备、前沿科研与超专科服务，并按地区需求在全国增设校区，坚持“服务即修行”。计划对标联合国可持续发展目标，聚焦预防、可负担治疗与弱势学生支持，她呼吁毕业生在技术之外守护患者尊严与终身学习。", "url": "https://x.com/i/trending/2112244933029761280", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-19T18:19:21.000Z"}, {"id": "2112802744491000212", "domain": "科学", "title_en": "UN Report: 1.5°C Target Now Requires Overshoot Before Return", "title_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转", "hook_en": "The world has missed the chance to hold global warming below 1.5°C without going over the line first, a new UN report warns. But swift action could still keep the exceedance short and pull temperatures back by 2100.", "hook_zh": "联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。", "summary_en": "The UN Environment Programme's Emissions Gap Report states that current policies point to up to 2.8°C of warming by century's end, while national pledges would limit it to 2.6°C. To minimize overshoot to 1.7-1.8°C mid-century with a fair shot at returning to 1.5°C by 2100, emissions must drop 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels. Key steps include tripling renewable electricity, slashing coal power by 75%, and cutting methane by 25%, as UN leaders like António Guterres urge pulling back from the brink ahead of COP31.", "summary_zh": "联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。UNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "body_en": "UN Report: 1.5°C Limit Overshoot Now Inevitable.\n\nYears of slow action have closed the door on staying below 1.5°C warming without a temporary breach. The focus shifts to limiting how high and how long temperatures climb before dropping back.\n\nThe UN Environment Programme’s 2026 Emissions Gap Report states that global warming will exceed the Paris Agreement’s 1.5°C target in coming years, with the best-case peak at 1.7–1.8°C mid-century and a 50% chance of returning below 1.5°C by 2100. This requires emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus large-scale carbon removal.\n\nCurrent pledges only achieve 5–8% cuts by 2030, heading toward 2.6°C or more warming. UNEP’s Inger Andersen calls for urgent action to minimize risks like floods and heatwaves ahead of COP31 talks.", "body_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转。\n\n联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。\n\n联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。\n\nUNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T16:57:31.000Z"}]};
